/** Late-bound DB flag shared between main.ts and the admin module. */
let dbAvailable = false;

export function setAdminDbAvailable(v: boolean): void {
  dbAvailable = v;
}

export function adminDbAvailable(): boolean {
  return dbAvailable;
}

/**
 * Admin surface (spec §29, roadmap 4b) — token-gated, ops-only.
 * GET  /admin/stats  → aggregate KPIs (players, runs, DAU, top fish, events)
 * PUT  /admin/config → DB-backed game-config override (single path=value per call)
 *
 * ADMIN_TOKEN is read once at boot; when unset the routes answer 503 so the
 * surface is closed by default in every environment.
 */
import type { FastifyInstance } from 'fastify';
import { setAdminDbAvailable, adminDbAvailable } from './admin-state.js';

const db = () => import('@fishkal/database').then((m) => m.prisma);

interface AdminStats {
  db: boolean;
  players: number;
  runs: number;
  referralsRewarded: number;
  dailyActive: { day: string; players: number; runs: number }[];
  topFish: { fishId: string; catches: number }[];
  events24h: { name: string; count: number }[];
}

export function adminRoutes(
  fastify: FastifyInstance,
  opts: {
    memoryPlayers: Map<string, { id: string; totalScore: number; displayName: string | null }>;
    memoryRuns: { playerId: string; createdAt: Date }[];
  },
): void {
  fastify.addHook('onRequest', async (req, reply) => {
    const expected = process.env.ADMIN_TOKEN;
    if (!expected) {
      return reply.code(503).send({ code: 'EXTERNAL_SERVICE_ERROR', message: 'ADMIN_TOKEN not configured' });
    }
    const header = req.headers.authorization;
    const provided = header?.startsWith('Bearer ') ? header.slice(7) : null;
    if (!provided || provided !== expected) {
      return reply.code(401).send({ code: 'AUTH_ERROR', message: 'Invalid admin token' });
    }
  });

  fastify.get('/admin/stats', async (): Promise<AdminStats> => {
    if (adminDbAvailable()) {
      const p = await db();
      const since = new Date(Date.now() - 7 * 86400_000);
      const [players, runs, referrals, runWindows, catchRows, eventRows] = await Promise.all([
        p.player.count(),
        p.gameRun.count(),
        p.referral.count({ where: { rewarded: true } }),
        p.gameRun.findMany({ where: { createdAt: { gte: since } }, select: { playerId: true, createdAt: true } }),
        p.gameRun.findMany({
          where: { createdAt: { gte: since } },
          select: { catches: { select: { fishId: true } } },
        }),
        p.analyticsEvent.groupBy({
          by: ['name'],
          where: { createdAt: { gte: new Date(Date.now() - 86400_000) } },
          _count: { name: true },
        }),
      ]);

      const byDay = new Map<string, { players: Set<string>; runs: number }>();
      for (let d = 6; d >= 0; d--) {
        const day = new Date(Date.now() - d * 86400_000).toISOString().slice(0, 10);
        byDay.set(day, { players: new Set(), runs: 0 });
      }
      for (const r of runWindows) {
        const key = r.createdAt.toISOString().slice(0, 10);
        const slot = byDay.get(key);
        if (slot) {
          slot.players.add(r.playerId);
          slot.runs += 1;
        }
      }

      const fishCount = new Map<string, number>();
      for (const row of catchRows) {
        for (const c of row.catches) fishCount.set(c.fishId, (fishCount.get(c.fishId) ?? 0) + 1);
      }

      return {
        db: true,
        players,
        runs,
        referralsRewarded: referrals,
        dailyActive: [...byDay.entries()].map(([day, v]) => ({ day, players: v.players.size, runs: v.runs })),
        topFish: [...fishCount.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([fishId, catches]) => ({ fishId, catches })),
        events24h: eventRows.map((e) => ({ name: e.name, count: e._count.name })),
      };
    }

    // In-memory fallback mirrors main.ts stores.
    const byDay = new Map<string, { players: Set<string>; runs: number }>();
    for (let d = 6; d >= 0; d--) {
      const day = new Date(Date.now() - d * 86400_000).toISOString().slice(0, 10);
      byDay.set(day, { players: new Set(), runs: 0 });
    }
    for (const r of opts.memoryRuns) {
      const key = r.createdAt.toISOString().slice(0, 10);
      const slot = byDay.get(key);
      if (slot) {
        slot.players.add(r.playerId);
        slot.runs += 1;
      }
    }
    return {
      db: false,
      players: opts.memoryPlayers.size,
      runs: opts.memoryRuns.length,
      referralsRewarded: 0,
      dailyActive: [...byDay.entries()].map(([day, v]) => ({ day, players: v.players.size, runs: v.runs })),
      topFish: [],
      events24h: [],
    };
  });

  fastify.put('/admin/config', async (req, reply) => {
    const body = (req.body ?? {}) as { path?: string; value?: unknown };
    if (!body.path || body.path.length > 64 || !/^[\w.]+$/.test(body.path)) {
      return reply.code(400).send({ code: 'VALIDATION_ERROR', message: 'path must be a dotted config path (e.g. engine.hookMoveSpeed)' });
    }
    if (body.value === undefined || body.value === null || typeof body.value === 'object') {
      return reply.code(400).send({ code: 'VALIDATION_ERROR', message: 'value must be a scalar' });
    }
    const { setConfigOverride } = await import('./config-overrides.js');
    await setConfigOverride(body.path, body.value);
    fastify.log.info({ path: body.path, value: body.value }, 'config override set');
    return { ok: true, overrides: await listOverrides() };
  });

  fastify.get('/admin/config', async () => ({ overrides: await listOverrides() }));

  async function listOverrides() {
    const { getConfigOverrides } = await import('./config-overrides.js');
    return getConfigOverrides();
  }
}

/**
 * Analytics ingestion + funnels (spec §30, §61, roadmap 5).
 * Clients POST named events with scalar props; the API persists them to
 * AnalyticsEvent (memory fallback mirrors every write) and ops compute
 * funnels/dashboards from GET /analytics/funnels.
 * Event names are whitelisted to keep the table queryable and PII-free.
 */
import { randomUUID } from 'node:crypto';

const db = () => import('@fishkal/database').then((m) => m.prisma);

export const ANALYTICS_EVENTS = [
  'session_start',
  'dive_start',
  'dive_end',
  'fish_caught',
  'shop_open',
  'upgrade_purchased',
  'mission_claimed',
  'referral_claimed',
  'results_view',
] as const;

export type AnalyticsEventName = (typeof ANALYTICS_EVENTS)[number];

interface MemEvent {
  id: string;
  name: string;
  playerId: string | null;
  props: Record<string, unknown> | null;
  createdAt: Date;
}

const memEvents: MemEvent[] = [];
let useDb = false;

export function setAnalyticsDbAvailable(v: boolean): void {
  useDb = v;
}

export async function trackEvent(
  name: string,
  playerId: string | null,
  props: Record<string, unknown> | undefined,
): Promise<void> {
  if (!(ANALYTICS_EVENTS as readonly string[]).includes(name)) {
    throw new Error(`unknown event: ${name}`);
  }
  // PII guard: only scalar props, no long strings.
  const clean: Record<string, unknown> | undefined = props
    ? Object.fromEntries(
        Object.entries(props)
          .filter(([, v]) => ['number', 'boolean', 'string'].includes(typeof v) && !(typeof v === 'string' && v.length > 64))
          .slice(0, 12),
      )
    : undefined;
  if (useDb) {
    try {
      const p = await db();
      await p.analyticsEvent.create({ data: { name, playerId, propsJson: (clean ?? undefined) as object | undefined } });
      return;
    } catch {
      useDb = false;
    }
  }
  memEvents.push({ id: randomUUID(), name, playerId, props: clean ?? null, createdAt: new Date() });
  if (memEvents.length > 10_000) memEvents.shift();
}

export interface FunnelResult {
  funnel: string[];
  counts: number[];
  conversion: number;
}

/** Compute a funnel over recent events (steps must be a subset of ANALYTICS_EVENTS). */
export async function funnel(steps: string[], windowHours = 24): Promise<FunnelResult> {
  const since = new Date(Date.now() - windowHours * 3600_000);
  let rows: { name: string; playerId: string | null }[];
  if (useDb) {
    try {
      const p = await db();
      rows = await p.analyticsEvent.findMany({
        where: { createdAt: { gte: since }, name: { in: steps } },
        select: { name: true, playerId: true },
      });
    } catch {
      useDb = false;
      rows = memEvents.filter((e) => e.createdAt >= since && steps.includes(e.name));
    }
  } else {
    rows = memEvents.filter((e) => e.createdAt >= since && steps.includes(e.name));
  }

  const counts = steps.map(
    (s) => new Set(rows.filter((r) => r.name === s).map((r) => r.playerId ?? 'anon')).size,
  );
  const first = counts[0] ?? 0;
  const last = counts[counts.length - 1] ?? 0;
  return { funnel: steps, counts, conversion: first > 0 ? last / first : 0 };
}

export async function eventsLast24h(): Promise<{ name: string; count: number }[]> {
  const since = new Date(Date.now() - 86400_000);
  if (useDb) {
    try {
      const p = await db();
      const rows = await p.analyticsEvent.groupBy({
        by: ['name'],
        where: { createdAt: { gte: since } },
        _count: { name: true },
      });
      return rows.map((r) => ({ name: r.name, count: r._count.name }));
    } catch {
      useDb = false;
    }
  }
  const counts = new Map<string, number>();
  for (const e of memEvents) {
    if (e.createdAt >= since) counts.set(e.name, (counts.get(e.name) ?? 0) + 1);
  }
  return [...counts.entries()].map(([name, count]) => ({ name, count }));
}

/**
 * Commerce scaffold (spec §33, roadmap 5) — intentionally data-gated.
 * The spec forbids inventing products/prices (§103: no fake data), so the
 * catalog starts EMPTY and the API answers 503 "catalog not configured"
 * until the business inserts real rows into Product (see schema) — at which
 * point this module activates with zero code changes.
 *
 * Order state machine: created → paid → delivered | cancelled.
 * Delivery of physical goods is out of process scope by design (ops CSV/API).
 */
export interface ProductView {
  id: string;
  name: string;
  description: string | null;
  priceAed: number;
  stock: number | null;
  active: boolean;
}

export interface OrderView {
  id: string;
  playerId: string;
  productId: string;
  quantity: number;
  priceAed: number;
  status: 'CREATED' | 'PAID' | 'DELIVERED' | 'CANCELLED';
  contact: string | null;
  createdAt: string;
}

interface OrderRow extends OrderView {}
const productMem: ProductView[] = []; // stays empty: gated on real data
const orderMem = new Map<string, OrderRow>();

const db = () => import('@fishkal/database').then((m) => m.prisma);
let useDb = false;

export function setCommerceDbAvailable(v: boolean): void {
  useDb = v;
}

/** Catalog only activates when the business provides real products. */
export async function listProducts(): Promise<{ available: boolean; products: ProductView[] }> {
  if (useDb) {
    try {
      const p = await db();
      const rows = await p.product.findMany({ where: { active: true }, orderBy: { priceAed: 'asc' } });
      return {
        available: rows.length > 0,
        products: rows.map((r) => ({ id: r.id, name: r.name, description: r.description, priceAed: r.priceAed, stock: r.stock, active: r.active })),
      };
    } catch {
      useDb = false;
    }
  }
  return { available: productMem.length > 0, products: [...productMem] };
}

export async function createOrder(playerId: string, productId: string, quantity: number, contact: string | null): Promise<{ ok: true; order: OrderView } | { ok: false; code: 'CATALOG_EMPTY' | 'UNKNOWN_PRODUCT' | 'OUT_OF_STOCK' }> {
  const { available, products } = await listProducts();
  if (!available) return { ok: false, code: 'CATALOG_EMPTY' };
  const product = products.find((p) => p.id === productId);
  if (!product) return { ok: false, code: 'UNKNOWN_PRODUCT' };
  if (product.stock !== null && product.stock < quantity) return { ok: false, code: 'OUT_OF_STOCK' };

  const order: OrderView = {
    id: crypto.randomUUID(),
    playerId,
    productId,
    quantity,
    priceAed: product.priceAed * quantity,
    status: 'CREATED',
    contact,
    createdAt: new Date().toISOString(),
  };
  orderMem.set(order.id, order);
  if (useDb) {
    try {
      const p = await db();
      await p.order.create({
        data: { id: order.id, playerId, productId, quantity, priceAed: order.priceAed, status: order.status },
      });
    } catch {
      useDb = false;
    }
  }
  return { ok: true, order };
}

export async function listOrders(playerId: string): Promise<OrderView[]> {
  if (useDb) {
    try {
      const p = await db();
      const rows = await p.order.findMany({ where: { playerId }, orderBy: { createdAt: 'desc' }, take: 50 });
      return rows.map((r) => ({
        id: r.id,
        playerId: r.playerId,
        productId: r.productId,
        quantity: r.quantity,
        priceAed: r.priceAed,
        status: r.status as OrderView['status'],
        contact: null,
        createdAt: r.createdAt.toISOString(),
      }));
    } catch {
      useDb = false;
    }
  }
  return [...orderMem.values()].filter((o) => o.playerId === playerId);
}

/**
 * DB-backed game-config overrides (roadmap 4c).
 * Scalar dotted-path overrides applied over DEFAULT_GAME_CONFIG — ops can
 * retune the live game without a redeploy (spec §29). Falls back to an
 * in-memory map when Postgres is unreachable; the active config is rebuilt
 * after every change so scoring and clients converge on one truth.
 */
import { DEFAULT_GAME_CONFIG } from '@fishkal/config';
import type { GameConfig } from '@fishkal/config';

export interface ConfigOverrideEntry {
  path: string;
  value: unknown;
  updatedBy: string | null;
  updatedAt: string;
}

const overridesMem = new Map<string, ConfigOverrideEntry>();
let useDb = false;

export function setOverridesDbAvailable(v: boolean): void {
  useDb = v;
}

const db = () => import('@fishkal/database').then((m) => m.prisma);

/** Set one scalar override; DB-backed when available, memory otherwise. */
export async function setConfigOverride(path: string, value: unknown, updatedBy: string | null = 'admin'): Promise<ConfigOverrideEntry> {
  const entry: ConfigOverrideEntry = { path, value, updatedBy, updatedAt: new Date().toISOString() };
  if (useDb) {
    try {
      const p = await db();
      await p.gameConfigEntry.upsert({
        where: { key: path },
        create: { key: path, valueJson: value as object },
        update: { valueJson: value as object },
      });
    } catch {
      useDb = false;
    }
  }
  overridesMem.set(path, entry);
  return entry;
}

export async function getConfigOverrides(): Promise<ConfigOverrideEntry[]> {
  if (useDb) {
    try {
      const p = await db();
      const rows = await p.gameConfigEntry.findMany({ orderBy: { key: 'asc' } });
      return rows.map((r) => ({ path: r.key, value: r.valueJson, updatedBy: null, updatedAt: r.updatedAt.toISOString() }));
    } catch {
      useDb = false;
    }
  }
  return [...overridesMem.values()];
}

/** Load persisted overrides from DB into the memory map (boot). */
export async function loadConfigOverrides(): Promise<void> {
  if (!useDb) return;
  try {
    const p = await db();
    const rows = await p.gameConfigEntry.findMany();
    for (const r of rows) {
      overridesMem.set(r.key, { path: r.key, value: r.valueJson, updatedBy: null, updatedAt: r.updatedAt.toISOString() });
    }
  } catch {
    useDb = false;
  }
}

/** Apply all scalar overrides over a config copy; unknown paths are ignored. */
export function applyOverrides(base: GameConfig = DEFAULT_GAME_CONFIG): GameConfig {
  const out: GameConfig = structuredClone(base);
  for (const { path, value } of overridesMem.values()) {
    const parts = path.split('.');
    if (parts.length === 0) continue;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let node: any = out;
    let ok = true;
    for (let i = 0; i < parts.length - 1; i++) {
      const seg = parts[i];
      if (seg !== undefined && node && typeof node === 'object' && seg in node) {
        node = node[seg];
      } else {
        ok = false;
        break;
      }
    }
    const last = parts[parts.length - 1];
    if (ok && last !== undefined && node && typeof node === 'object' && last in node) {
      // Never let an override change a value's type.
      if (typeof node[last] === typeof value) node[last] = value;
    }
  }
  return out;
}

/** The live config used for scoring and served to clients. */
export function activeConfig(): GameConfig {
  return applyOverrides();
}

/**
 * Economy security tests (roadmap Block D — §58–60, §17).
 * Exercises the in-memory path of EconomyStore directly: the same guards
 * (idempotent refIds, pay-once claims, overdraft rejection) wrap the DB path.
 */
import { describe, expect, it } from 'vitest';
import { EconomyStore } from './economy.js';

function store(): EconomyStore {
  return new EconomyStore(false); // force memory path
}

describe('EconomyStore (server-authoritative guards)', () => {
  it('rejects credit of non-positive or non-integer deltas', async () => {
    const s = store();
    expect(await s.credit('p1', 0, 'zero', null)).toBe(false);
    expect(await s.credit('p1', -5, 'negative', null)).toBe(false);
    expect(await s.credit('p1', 1.5, 'fraction', null)).toBe(false);
  });

  it('is idempotent per (reason, refId): replayed credit pays once', async () => {
    const s = store();
    expect(await s.credit('p1', 10, 'run_reward', 'run-1')).toBe(true);
    expect(await s.credit('p1', 10, 'run_reward', 'run-1')).toBe(false); // replay
    expect(await s.credit('p1', 10, 'run_reward', 'run-2')).toBe(true); // new ref ok
    const wallet = await s.getWallet('p1', 20);
    expect(wallet.ledger).toHaveLength(2);
  });

  it('purchase rejects unknown upgrade, overdraft, and duplicate refIds', async () => {
    const s = store();
    const unknown = await s.purchase('p1', 'nope', 'r1', 100);
    expect(unknown.ok).toBe(false);
    const broke = await s.purchase('p1', 'line_length', 'r1', 10);
    expect(!broke.ok && broke.code).toBe('INSUFFICIENT_CREDITS');

    const ok = await s.purchase('p1', 'line_length', 'r2', 100);
    expect(ok.ok).toBe(true);
    if (ok.ok) {
      expect(ok.level).toBe(1);
      // line_length level 1 cost = 50 * 1.7^0 = 50 → delta -50
      expect(ok.delta).toBe(-50);
      expect(ok.loadout.lineLength).toBe(1);
    }
    // Same refId replays are rejected even with money available.
    const dup = await s.purchase('p1', 'hook_strength', 'r2', 100);
    expect(!dup.ok && dup.code).toBe('DUPLICATE');
  });

  it('purchase cost escalates by multiplier and stops at max level', async () => {
    const s = store();
    let credits = 10_000;
    let level = 0;
    // magnet_radius: maxLevel 5
    for (let i = 0; i < 5; i++) {
      const r = await s.purchase('p1', 'magnet_radius', `ref-${i}`, credits);
      if (!r.ok) throw new Error(`purchase ${i} failed: ${r.code}`);
      credits += r.delta;
      level = r.level;
    }
    expect(level).toBe(5);
    const capped = await s.purchase('p1', 'magnet_radius', 'ref-99', credits);
    expect(capped.ok).toBe(false);
    if (!capped.ok) expect(capped.code).toBe('MAX_LEVEL');
  });

  it('missions: claim requires completion and pays exactly once', async () => {
    const s = store();
    const early = await s.claimMission('p1', 'first_catch', 0);
    expect(!early.ok && early.code).toBe('NOT_COMPLETE');
    await s.addMissionProgress('p1', 'catches', 1);
    const claimed = await s.claimMission('p1', 'first_catch', 5);
    expect(claimed.ok).toBe(true);
    if (claimed.ok) expect(claimed.delta).toBe(10); // reward delta
    const again = await s.claimMission('p1', 'first_catch', 15);
    expect(!again.ok && again.code).toBe('ALREADY_CLAIMED');
  });

  it('progress is capped at the mission target', async () => {
    const s = store();
    await s.addMissionProgress('p1', 'depth', 5000);
    const missions = await s.getMissions('p1');
    const deep = missions.find((m) => m.kind === 'depth');
    expect(deep?.progress).toBe(deep?.target);
    expect(deep?.claimable).toBe(true);
  });

  it('collection records best score/depth per species', async () => {
    const s = store();
    const scores = new Map([['sardine', 10]]);
    await s.recordCollection('p1', [{ fishId: 'sardine', depth: 40 }], scores);
    await s.recordCollection('p1', [{ fishId: 'sardine', depth: 60 }], new Map([['sardine', 30]]));
    const coll = await s.getCollection('p1');
    expect(coll).toHaveLength(1);
    expect(coll[0]?.bestDepth).toBe(60);
    expect(coll[0]?.bestScore).toBe(30);
  });

  it('loadout levels persist across purchases', async () => {
    const s = store();
    await s.purchase('p1', 'reel_speed', 'a', 1000);
    await s.purchase('p1', 'reel_speed', 'b', 1000);
    const loadout = await s.getLoadout('p1');
    expect(loadout.reelSpeed).toBe(2);
    expect(loadout.lineLength).toBe(0); // untouched
  });
});

/**
 * Server-authoritative economy (spec §60, roadmap 3.1–3.2).
 * All credit mutations flow through the CreditLedger inside transactions.
 * Works on Postgres when available; falls back to in-memory maps otherwise
 * (same pattern as the Phase 1 store) so dev never blocks on Docker.
 */
import { DEFAULT_GAME_CONFIG } from '@fishkal/config';
import type { PlayerLoadout } from '@fishkal/game-core';
import { DEFAULT_LOADOUT } from '@fishkal/game-core';

export interface WalletView {
  credits: number;
  ledger: { delta: number; reason: string; refId: string | null; createdAt: string }[];
}

export interface UpgradeView {
  id: string;
  name: string;
  description: string;
  level: number;
  maxLevel: number;
  nextCost: number | null;
}

export interface MissionView {
  id: string;
  titleKey: string;
  descriptionKey: string;
  kind: string;
  target: number;
  progress: number;
  rewardCredits: number;
  claimable: boolean;
  claimed: boolean;
}

const db = () => import('@fishkal/database').then((m) => m.prisma);

// ---- In-memory fallback stores ---------------------------------------------

interface EconPlayer {
  credits: number;
  upgrades: Map<string, number>;
  loadout: PlayerLoadout;
  missions: Map<string, { progress: number; claimedAt: Date | null }>;
  ledger: { delta: number; reason: string; refId: string | null; createdAt: string }[];
  ledgerRefs: Set<string>;
}

export class EconomyStore {
  private mem = new Map<string, EconPlayer>();
  private dbAvailable: boolean;

  constructor(dbAvailable: boolean) {
    this.dbAvailable = dbAvailable;
  }

  setDbAvailable(v: boolean): void {
    this.dbAvailable = v;
  }

  private memPlayer(playerId: string): EconPlayer {
    let p = this.mem.get(playerId);
    if (!p) {
      p = {
        credits: 0,
        upgrades: new Map(),
        loadout: { ...DEFAULT_LOADOUT },
        missions: new Map(),
        ledger: [],
        ledgerRefs: new Set(),
      };
      this.mem.set(playerId, p);
    }
    return p;
  }

  // ---- Costing ----------------------------------------------------------------

  /** Cost of buying `level` (the level being purchased, 1-based). */
  static upgradeCost(upgradeId: string, level: number): number {
    const def = DEFAULT_GAME_CONFIG.upgrades.find((u) => u.id === upgradeId);
    if (!def) throw new Error(`unknown upgrade ${upgradeId}`);
    return Math.round(def.baseCost * Math.pow(def.costMultiplier, level - 1));
  }

  // ---- Loadout ----------------------------------------------------------------

  static loadoutFromLevels(u: { hookStrength: number; lineStrength: number; lineLength: number; reelSpeed: number; magnetRadius: number }): PlayerLoadout {
    return { ...u };
  }

  async getLoadout(playerId: string): Promise<PlayerLoadout> {
    if (this.dbAvailable) {
      try {
        const p = await db();
        const rows = await p.playerUpgrade.findMany({ where: { playerId } });
        const levels = { ...DEFAULT_LOADOUT };
        for (const r of rows) {
          if (r.upgradeId in levels) levels[r.upgradeId as keyof PlayerLoadout] = r.level;
        }
        return levels;
      } catch {
        this.dbAvailable = false;
      }
    }
    return { ...this.memPlayer(playerId).loadout };
  }

  // ---- Wallet -----------------------------------------------------------------

  async getWallet(playerId: string, currentCredits: number): Promise<WalletView> {
    if (this.dbAvailable) {
      try {
        const p = await db();
        const rows = await p.creditLedger.findMany({
          where: { playerId },
          orderBy: { createdAt: 'desc' },
          take: 20,
        });
        return {
          credits: currentCredits,
          ledger: rows.map((r) => ({
            delta: r.delta,
            reason: r.reason,
            refId: r.refId,
            createdAt: r.createdAt.toISOString(),
          })),
        };
      } catch {
        this.dbAvailable = false;
      }
    }
    const mem = this.memPlayer(playerId);
    return { credits: currentCredits, ledger: mem.ledger.slice(0, 20) };
  }

  /** Credit a ledger row. `refId` makes it idempotent (replay-safe, §59). */
  async credit(playerId: string, delta: number, reason: string, refId: string | null): Promise<boolean> {
    if (delta <= 0 || !Number.isInteger(delta)) return false;
    if (this.dbAvailable) {
      try {
        const p = await db();
        const dup = refId
          ? await p.creditLedger.findFirst({ where: { playerId, reason, refId } })
          : null;
        if (dup) return false;
        await p.$transaction(async (tx) => {
          await tx.creditLedger.create({ data: { playerId, delta, reason, refId } });
          await tx.player.update({ where: { id: playerId }, data: { credits: { increment: delta } } });
        });
        return true;
      } catch {
        this.dbAvailable = false;
      }
    }
    const mem = this.memPlayer(playerId);
    if (refId && mem.ledgerRefs.has(`${reason}:${refId}`)) return false;
    // Balance itself lives in the caller's player record (single source of truth);
    // the store owns the ledger + replay protection only.
    mem.ledger.unshift({ delta, reason, refId, createdAt: new Date().toISOString() });
    if (refId) mem.ledgerRefs.add(`${reason}:${refId}`);
    return true;
  }

  // ---- Upgrades ---------------------------------------------------------------

  async getUpgrades(playerId: string): Promise<UpgradeView[]> {
    const levels = await this.getLevels(playerId);
    return DEFAULT_GAME_CONFIG.upgrades.map((def) => {
      const level = levels[def.id as keyof PlayerLoadout] ?? 0;
      const nextCost = level < def.maxLevel ? EconomyStore.upgradeCost(def.id, level + 1) : null;
      return { id: def.id, name: def.name, description: def.description, level, maxLevel: def.maxLevel, nextCost };
    });
  }

  async getLevels(playerId: string): Promise<PlayerLoadout> {
    return this.getLoadout(playerId);
  }

  /**
   * Purchase the next level of an upgrade. Idempotent by refId.
   * Returns the balance DELTA — the caller owns the authoritative balance
   * (single writer; the split-brain bug this fixes is documented in BUILD_STATE).
   */
  async purchase(
    playerId: string,
    upgradeId: string,
    refId: string,
    currentCredits: number,
  ): Promise<
    | { ok: true; delta: number; level: number; loadout: PlayerLoadout }
    | { ok: false; code: 'UNKNOWN_UPGRADE' | 'MAX_LEVEL' | 'INSUFFICIENT_CREDITS' | 'DUPLICATE' }
  > {
    const def = DEFAULT_GAME_CONFIG.upgrades.find((u) => u.id === upgradeId);
    if (!def) return { ok: false, code: 'UNKNOWN_UPGRADE' };

    if (this.dbAvailable) {
      try {
        const p = await db();
        const dup = await p.creditLedger.findFirst({ where: { playerId, reason: 'upgrade_purchase', refId } });
        if (dup) return { ok: false, code: 'DUPLICATE' };
        const result = await p.$transaction(async (tx) => {
          const player = await tx.player.findUniqueOrThrow({ where: { id: playerId } });
          const row = await tx.playerUpgrade.upsert({
            where: { playerId_upgradeId: { playerId, upgradeId } },
            create: { playerId, upgradeId, level: 0 },
            update: {},
          });
          if (row.level >= def.maxLevel) return { ok: false as const, code: 'MAX_LEVEL' as const };
          const cost = EconomyStore.upgradeCost(upgradeId, row.level + 1);
          if (player.credits < cost) return { ok: false as const, code: 'INSUFFICIENT_CREDITS' as const };
          await tx.player.update({
            where: { id: playerId },
            data: { credits: { decrement: cost } },
          });
          await tx.playerUpgrade.update({
            where: { playerId_upgradeId: { playerId, upgradeId } },
            data: { level: { increment: 1 } },
          });
          await tx.creditLedger.create({
            data: { playerId, delta: -cost, reason: 'upgrade_purchase', refId },
          });
          return { ok: true as const, level: row.level + 1, delta: -cost };
        });
        if (!result.ok) return { ok: false, code: result.code };
        const loadout = await this.getLoadout(playerId);
        return { ok: true, delta: result.delta, level: result.level, loadout };
      } catch {
        this.dbAvailable = false;
      }
    }

    // Memory path — same guarantees.
    const mem = this.memPlayer(playerId);
    const refKey = `upgrade_purchase:${refId}`;
    if (mem.ledgerRefs.has(refKey)) return { ok: false, code: 'DUPLICATE' };
    const cur = mem.upgrades.get(upgradeId) ?? 0;
    if (cur >= def.maxLevel) return { ok: false, code: 'MAX_LEVEL' };
    const cost = EconomyStore.upgradeCost(upgradeId, cur + 1);
    // currentCredits (caller's authoritative balance) decides affordability.
    if (currentCredits < cost) return { ok: false, code: 'INSUFFICIENT_CREDITS' };
    mem.upgrades.set(upgradeId, cur + 1);
    applyUpgradeToLoadout(mem.loadout, upgradeId, cur + 1);
    mem.ledger.unshift({ delta: -cost, reason: 'upgrade_purchase', refId, createdAt: new Date().toISOString() });
    mem.ledgerRefs.add(refKey);
    return { ok: true, delta: -cost, level: cur + 1, loadout: { ...mem.loadout } };
  }

  // ---- Missions ---------------------------------------------------------------

  async getMissions(playerId: string): Promise<MissionView[]> {
    if (this.dbAvailable) {
      try {
        const p = await db();
        const defs = await p.missionDef.findMany({ where: { active: true } });
        const progress = await p.missionProgress.findMany({ where: { playerId } });
        const byId = new Map(progress.map((m) => [m.missionId, m]));
        return defs.map((d) => {
          const pr = byId.get(d.id);
          const prog = pr?.progress ?? 0;
          return {
            id: d.id,
            titleKey: d.titleKey,
            descriptionKey: d.descriptionKey,
            kind: d.kind,
            target: d.target,
            progress: prog,
            rewardCredits: d.rewardCredits,
            claimable: prog >= d.target && !pr?.claimedAt,
            claimed: !!pr?.claimedAt,
          };
        });
      } catch {
        this.dbAvailable = false;
      }
    }
    const mem = this.memPlayer(playerId);
    return DEFAULT_MISSIONS.map((d) => {
      const pr = mem.missions.get(d.id);
      const prog = pr?.progress ?? 0;
      return {
        id: d.id,
        titleKey: d.titleKey,
        descriptionKey: d.descriptionKey,
        kind: d.kind,
        target: d.target,
        progress: prog,
        rewardCredits: d.rewardCredits,
        claimable: prog >= d.target && !pr?.claimedAt,
        claimed: !!pr?.claimedAt,
      };
    });
  }

  /** Advance progress (max target) for all active missions of a kind. */
  async addMissionProgress(playerId: string, kind: string, amount: number): Promise<void> {
    if (this.dbAvailable) {
      try {
        const p = await db();
        const defs = await p.missionDef.findMany({ where: { active: true, kind } });
        for (const d of defs) {
          const row = await p.missionProgress.upsert({
            where: { playerId_missionId: { playerId, missionId: d.id } },
            create: { playerId, missionId: d.id, progress: Math.min(amount, d.target) },
            update: { progress: { increment: amount } },
          });
          if (row.progress > d.target) {
            await p.missionProgress.update({ where: { id: row.id }, data: { progress: d.target } });
          }
        }
        return;
      } catch {
        this.dbAvailable = false;
      }
    }
    const mem = this.memPlayer(playerId);
    for (const d of DEFAULT_MISSIONS.filter((m) => m.kind === kind)) {
      const cur = mem.missions.get(d.id) ?? { progress: 0, claimedAt: null };
      cur.progress = Math.min(d.target, cur.progress + amount);
      mem.missions.set(d.id, cur);
    }
  }

  /** Claim mission reward — pay-once guaranteed by claimedAt guard + ledger refId.
   * Returns the positive DELTA; the caller owns the authoritative balance. */
  async claimMission(
    playerId: string,
    missionId: string,
    currentCredits: number,
  ): Promise<{ ok: true; delta: number; reward: number } | { ok: false; code: 'UNKNOWN_MISSION' | 'NOT_COMPLETE' | 'ALREADY_CLAIMED' }> {
    const def =
      DEFAULT_MISSIONS.find((m) => m.id === missionId);
    if (!def) return { ok: false, code: 'UNKNOWN_MISSION' };

    if (this.dbAvailable) {
      try {
        const p = await db();
        const dbDef = await p.missionDef.findUnique({ where: { id: missionId } });
        if (!dbDef) return { ok: false, code: 'UNKNOWN_MISSION' };
        const result = await p.$transaction(async (tx) => {
          const row = await tx.missionProgress.upsert({
            where: { playerId_missionId: { playerId, missionId } },
            create: { playerId, missionId, progress: 0 },
            update: {},
          });
          if (row.claimedAt) return { ok: false as const, code: 'ALREADY_CLAIMED' as const };
          if (row.progress < dbDef.target) return { ok: false as const, code: 'NOT_COMPLETE' as const };
          await tx.missionProgress.update({ where: { id: row.id }, data: { claimedAt: new Date() } });
          await tx.creditLedger.create({
            data: { playerId, delta: dbDef.rewardCredits, reason: `mission:${missionId}`, refId: missionId },
          });
          return { ok: true as const, reward: dbDef.rewardCredits, delta: dbDef.rewardCredits };
        });
        if (!result.ok) return { ok: false, code: result.code };
        return { ok: true, delta: result.delta, reward: result.reward };
      } catch {
        this.dbAvailable = false;
      }
    }

    const mem = this.memPlayer(playerId);
    const pr = mem.missions.get(missionId) ?? { progress: 0, claimedAt: null };
    if (pr.claimedAt) return { ok: false, code: 'ALREADY_CLAIMED' };
    if (pr.progress < def.target) return { ok: false, code: 'NOT_COMPLETE' };
    pr.claimedAt = new Date();
    mem.missions.set(missionId, pr);
    mem.ledger.unshift({ delta: def.rewardCredits, reason: `mission:${missionId}`, refId: missionId, createdAt: new Date().toISOString() });
    mem.ledgerRefs.add(`mission:${missionId}`);
    return { ok: true, delta: def.rewardCredits, reward: def.rewardCredits };
  }

  // ---- Collection ---------------------------------------------------------------

  async getCollection(playerId: string): Promise<{ fishId: string; bestScore: number; bestDepth: number; caughtAt: string }[]> {
    if (this.dbAvailable) {
      try {
        const p = await db();
        const rows = await p.playerCollection.findMany({ where: { playerId } });
        return rows.map((r) => ({
          fishId: r.fishId,
          bestScore: r.bestScore,
          bestDepth: r.bestDepth,
          caughtAt: r.caughtAt.toISOString(),
        }));
      } catch {
        this.dbAvailable = false;
      }
    }
    return collectionMem.get(playerId) ?? [];
  }

  /** Record discovered species (§25 collection). Best score/depth kept per fish. */
  async recordCollection(playerId: string, catches: { fishId: string; depth: number }[], scoreByFish: Map<string, number>): Promise<void> {
    if (catches.length === 0) return;
    if (this.dbAvailable) {
      try {
        const p = await db();
        for (const c of catches) {
          const existing = await p.playerCollection.findUnique({
            where: { playerId_fishId: { playerId, fishId: c.fishId } },
          });
          const bestScore = Math.max(existing?.bestScore ?? 0, scoreByFish.get(c.fishId) ?? 0);
          const bestDepth = Math.max(existing?.bestDepth ?? 0, c.depth);
          await p.playerCollection.upsert({
            where: { playerId_fishId: { playerId, fishId: c.fishId } },
            create: { playerId, fishId: c.fishId, bestDepth, bestScore },
            update: { bestDepth, bestScore },
          });
        }
        return;
      } catch {
        this.dbAvailable = false;
      }
    }
    const list = collectionMem.get(playerId) ?? [];
    for (const c of catches) {
      const ex = list.find((e) => e.fishId === c.fishId);
      const score = scoreByFish.get(c.fishId) ?? 0;
      if (ex) {
        ex.bestScore = Math.max(ex.bestScore, score);
        ex.bestDepth = Math.max(ex.bestDepth, c.depth);
      } else {
        list.push({ fishId: c.fishId, bestScore: score, bestDepth: c.depth, caughtAt: new Date().toISOString() });
      }
    }
    collectionMem.set(playerId, list);
  }
}

// ---- Referrals (spec §52) ---------------------------------------------------

export interface ReferralInfo {
  referrerId: string | null;
  invited: { playerId: string; displayName: string | null; rewarded: boolean }[];
  rewardCredits: number;
  claimed: boolean;
  claimable: boolean;
}

export const REFERRAL_REWARD_CREDITS = 20;
const referralMem = new Map<string, { referrerId: string; rewarded: boolean }>();

export class ReferralStore {
  /** Idempotent: first referrer wins; self-referral rejected. */
  async attach(refereeId: string, referrerId: string): Promise<boolean> {
    if (refereeId === referrerId) return false;
    if (this.dbAvailable) {
      try {
        const p = await db();
        const created = await p.referral.createMany({
          data: [{ referrerId, refereeId }],
          skipDuplicates: true,
        });
        return created.count > 0;
      } catch {
        this.dbAvailable = false;
      }
    }
    if (referralMem.has(refereeId)) return false;
    referralMem.set(refereeId, { referrerId, rewarded: false });
    return true;
  }

  async info(refereeId: string): Promise<ReferralInfo> {
    if (this.dbAvailable) {
      try {
        const p = await db();
        const rows = await p.referral.findMany({ where: { referrerId: refereeId } });
        const names = await p.player.findMany({
          where: { id: { in: rows.map((r) => r.refereeId) } },
          select: { id: true, displayName: true },
        });
        const nameOf = new Map(names.map((n) => [n.id, n.displayName]));
        return {
          referrerId: null,
          invited: rows.map((r) => ({
            playerId: r.refereeId,
            displayName: nameOf.get(r.refereeId) ?? null,
            rewarded: r.rewarded,
          })),
          rewardCredits: REFERRAL_REWARD_CREDITS,
          claimed: rows.length > 0 && rows.every((r) => r.rewarded),
          claimable: rows.length > 0 && rows.some((r) => !r.rewarded),
        };
      } catch {
        this.dbAvailable = false;
      }
    }
    const invited = [...referralMem.entries()]
      .filter(([, v]) => v.referrerId === refereeId)
      .map(([k, v]) => ({ playerId: k, displayName: null, rewarded: v.rewarded }));
    return {
      referrerId: null,
      invited,
      rewardCredits: REFERRAL_REWARD_CREDITS,
      claimed: invited.length > 0 && invited.every((i) => i.rewarded),
      claimable: invited.length > 0 && invited.some((i) => !i.rewarded),
    };
  }

  /** Mark all un-rewarded invitees as rewarded; returns the total delta to apply. */
  async claim(refereeId: string): Promise<{ ok: true; reward: number } | { ok: false; code: 'NOTHING_TO_CLAIM' }> {
    if (this.dbAvailable) {
      try {
        const p = await db();
        const upd = await p.referral.updateMany({
          where: { referrerId: refereeId, rewarded: false },
          data: { rewarded: true },
        });
        if (upd.count === 0) return { ok: false, code: 'NOTHING_TO_CLAIM' };
        return { ok: true, reward: upd.count * REFERRAL_REWARD_CREDITS };
      } catch {
        this.dbAvailable = false;
      }
    }
    let count = 0;
    for (const v of referralMem.values()) {
      if (v.referrerId === refereeId && !v.rewarded) {
        v.rewarded = true;
        count += 1;
      }
    }
    if (count === 0) return { ok: false, code: 'NOTHING_TO_CLAIM' };
    return { ok: true, reward: count * REFERRAL_REWARD_CREDITS };
  }

  setDbAvailable(v: boolean): void {
    this.dbAvailable = v;
  }

  constructor(private dbAvailable: boolean) {}
}

