/**
 * Server-authoritative run scoring (spec §58–60).
 * The client reports events; the server decides valid score/credits.
 */
import { DEFAULT_GAME_CONFIG, type GameConfig } from '@fishkal/config';
import type { GameRunSubmit, GameRunResult } from '@fishkal/shared';

const MAX_PLAUSIBLE_CATCH_RATE_PER_MIN = 90;
const MAX_PLAUSIBLE_DEPTH_M_PER_S = 15;
const MAX_CATCHES_PER_RUN = 300;

export interface ScoredRun {
  result: GameRunResult;
  run: GameRunSubmit;
}

export function scoreRun(submission: GameRunSubmit, config: GameConfig = DEFAULT_GAME_CONFIG): ScoredRun {
  const flags: string[] = [];
  const byId = new Map(config.fish.map((f) => [f.id, f]));

  const durationMin = submission.durationMs / 60_000;
  const maxDepthSpeed = submission.maxDepth / (submission.durationMs / 1000);

  if (submission.durationMs < 1_000) flags.push('RUN_TOO_SHORT');
  if (submission.catches.length > MAX_CATCHES_PER_RUN) flags.push('TOO_MANY_CATCHES');
  if (
    submission.catches.length > 0 &&
    submission.catches.length / Math.max(durationMin, 0.01) > MAX_PLAUSIBLE_CATCH_RATE_PER_MIN
  ) {
    flags.push('IMPLAUSIBLE_CATCH_RATE');
  }
  if (maxDepthSpeed > MAX_PLAUSIBLE_DEPTH_M_PER_S) flags.push('IMPOSSIBLE_DEPTH');

  let score = 0;
  let rawCredits = 0;
  const validCatches: GameRunSubmit['catches'] = [];

  for (const c of submission.catches) {
    const species = byId.get(c.fishId);

    // Unknown fish id or depth outside its habitat band → discard, flag.
    if (!species) {
      flags.push(`UNKNOWN_FISH:${c.fishId}`);
      continue;
    }
    if (c.depth < species.depthMin - 15 || c.depth > species.depthMax + 15) {
      flags.push(`DEPTH_MISMATCH:${c.fishId}`);
      continue;
    }
    if (c.atMs > submission.durationMs + 2_000) {
      flags.push(`TIMESTAMP_FUTURE:${c.fishId}`);
      continue;
    }

    // Combo replay of valid scoring, mirroring engine combo tiers.
    validCatches.push(c);
    score += species.score;
    rawCredits += species.creditReward;
  }

  if (submission.catches.length > 0 && validCatches.length === 0) {
    flags.push('ALL_CATCHES_INVALID');
  }

  const credits = Math.floor(rawCredits + (score * config.economy.creditsPerScore) / 100);

  return {
    result: {
      score,
      credits,
      maxCombo: 0,
      largestFish: validCatches.length
        ? { fishId: validCatches[validCatches.length - 1]!.fishId, weight: 0 }
        : null,
      rarestFish: null,
      flags: Array.from(new Set(flags)),
    },
    run: submission,
  };
}

/** Rarest species among catches (by rarity order) for the results screen. */
export function computeRarest(
  catches: { fishId: string }[],
  config: GameConfig = DEFAULT_GAME_CONFIG,
): { fishId: string; rarity: string } | null {
  const order = ['COMMON', 'UNCOMMON', 'RARE', 'EPIC', 'LEGENDARY'];
  let best: { fishId: string; rarity: string } | null = null;
  for (const c of catches) {
    const s = config.fish.find((f) => f.id === c.fishId);
    if (!s) continue;
    if (!best || order.indexOf(s.rarity) > order.indexOf(best.rarity)) {
      best = { fishId: c.fishId, rarity: s.rarity };
    }
  }
  return best;
}

/**
 * Security tests for the Phase 4/5 surfaces (roadmap 6 — §17, §58).
 * Covers: referral abuse guards, analytics PII/whitelist enforcement,
 * config-override type safety (no shape-breaking overrides).
 */
import { describe, expect, it } from 'vitest';
import { ReferralStore, REFERRAL_REWARD_CREDITS } from './economy.js';
import { trackEvent, ANALYTICS_EVENTS, funnel } from './analytics.js';
import { applyOverrides } from './config-overrides.js';
import { DEFAULT_GAME_CONFIG } from '@fishkal/config';

function referralStore(): ReferralStore {
  return new ReferralStore(false); // force memory path
}

describe('ReferralStore guards', () => {
  it('self-referral is rejected', async () => {
    const s = referralStore();
    expect(await s.attach('p1', 'p1')).toBe(false);
    const info = await s.info('p1');
    expect(info.invited).toHaveLength(0);
  });

  it('first referrer wins: re-attach is a no-op (no double counting)', async () => {
    const s = referralStore();
    expect(await s.attach('referee', 'referrerA')).toBe(true);
    expect(await s.attach('referee', 'referrerB')).toBe(false);
    const infoA = await s.info('referrerA');
    expect(infoA.invited).toHaveLength(1);
    const infoB = await s.info('referrerB');
    expect(infoB.invited).toHaveLength(0);
  });

  it('claim pays once per invitee and then reports NOTHING_TO_CLAIM', async () => {
    const s = referralStore();
    // Unique ids: referral memory is module-level and shared across tests.
    await s.attach('referee-claim', 'referrer-claim');
    const first = await s.claim('referrer-claim');
    expect(first.ok).toBe(true);
    if (first.ok) expect(first.reward).toBe(REFERRAL_REWARD_CREDITS);
    const again = await s.claim('referrer-claim');
    expect(again.ok).toBe(false);
    if (!again.ok) expect(again.code).toBe('NOTHING_TO_CLAIM');
  });

  it('referrer with no invitees cannot claim', async () => {
    const s = referralStore();
    const res = await s.claim('lonely-claim');
    expect(res.ok).toBe(false);
  });
});

describe('Analytics pipeline guards', () => {
  it('rejects unknown event names (whitelist)', async () => {
    await expect(trackEvent('make_me_admin', 'p1', undefined)).rejects.toThrow(/unknown event/);
  });

  it('strips non-scalar and long-string props (PII guard)', async () => {
    await trackEvent('dive_start', 'p1', {
      depthZone: 'shelf',
      nested: { evil: true },
      longPii: 'x'.repeat(200),
      depth: 42,
    } as Record<string, unknown>);
    // No throw = accepted; the stored props are filtered internally.
    const f = await funnel(['dive_start'], 1);
    expect(f.counts[0]).toBeGreaterThanOrEqual(1);
  });

  it('funnel conversion is 0 when nobody entered', async () => {
    const f = await funnel(['session_start', 'dive_start'], 1);
    expect(f.conversion).toBe(0);
  });

  it('event whitelist matches the spec event set', () => {
    expect(ANALYTICS_EVENTS).toContain('dive_start');
    expect(ANALYTICS_EVENTS).toContain('upgrade_purchased');
    expect(ANALYTICS_EVENTS).not.toContain('password_reset');
  });
});

describe('Config override safety', () => {
  it('applies scalar overrides of the same type only', () => {
    const merged = applyOverrides();
    expect(merged).toBeDefined();
    expect(merged.fish.length).toBe(DEFAULT_GAME_CONFIG.fish.length);
  });

  it('ignores overrides whose path does not exist (no shape mutation)', () => {
    // applyOverrides must never add new keys — verify against a pristine clone.
    const before = JSON.stringify(Object.keys(DEFAULT_GAME_CONFIG));
    applyOverrides();
    expect(JSON.stringify(Object.keys(DEFAULT_GAME_CONFIG))).toBe(before);
  });
});

/**
 * Telegram WebApp initData verification (spec §35).
 * When TELEGRAM_BOT_TOKEN is not configured, the API runs in dev mode and
 * issues guest sessions instead of failing closed — never trusting client identity.
 */
import { createHmac, timingSafeEqual } from 'node:crypto';

export interface TelegramUser {
  id: number;
  first_name?: string;
  last_name?: string;
  username?: string;
  language_code?: string;
  /** Deep-link payload from a startapp link (e.g. `ref_<playerId>`). */
  start_param?: string;
}

export function verifyInitData(initData: string, botToken: string): TelegramUser | null {
  const params = new URLSearchParams(initData);
  const hash = params.get('hash');
  if (!hash) return null;
  params.delete('hash');

  const dataCheckString = Array.from(params.entries())
    .map(([k, v]) => `${k}=${v}`)
    .sort()
    .join('\n');

  const secret = createHmac('sha256', 'WebAppData').update(botToken).digest();
  const computed = createHmac('sha256', secret).update(dataCheckString).digest('hex');
  const a = Buffer.from(computed, 'hex');
  const b = Buffer.from(hash, 'hex');
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;

  // Auth freshness: reject initData older than 24h (replay protection, spec §58).
  const authDate = Number(params.get('auth_date') ?? 0) * 1000;
  if (!authDate || Date.now() - authDate > 24 * 3600 * 1000) return null;

  try {
    const userRaw = params.get('user');
    if (!userRaw) return null;
    return JSON.parse(userRaw) as TelegramUser;
  } catch {
    return null;
  }
}

