export const prisma: PrismaClient = globalThis.__fishkalPrisma ?? new PrismaClient();
if (process.env.NODE_ENV !== 'production') {
  globalThis.__fishkalPrisma = prisma;
}

export { prisma } from './client.js';
export { seed } from './seed.js';
