  hooked: boolean;
  nextTurnAt: number;
  /** Reel-seconds left before this fish gives up (set on attach). */
  stamina: number;
}

export interface EngineOptions {
  config: GameConfig;
  loadout?: PlayerLoadout;
  seed?: number;
  onStateChange?: (state: GameState) => void;
  onEvent?: (event: GameEvent) => void;
}

export interface EngineStats {
  score: number;
  catches: number;
  maxCombo: number;
  maxDepth: number;
  elapsedMs: number;
  provisionalCredits: number;
}

export class FishkalEngine {
  readonly config: GameConfig;
  private loadout: PlayerLoadout;
  private readonly rng: Rng;
  private readonly onStateChange?: (s: GameState) => void;
  private readonly onEvent?: (e: GameEvent) => void;

  private state: GameState = 'READY';
  private hookState: HookState = 'READY';
  private hookX = 0;
  private inputX = 0;
  private hookDepth = 0;
  private tension = 0;
  private reeling = false;
  private brokenUntil = 0;
  private hitInvulnUntil = 0;
  private dangerUntil = 0;

  private fish: FishEntity[] = [];
  private nextEntityId = 1;
  private spawnTimer = 0.5;

  private score = 0;
  private credits = 0;
  private combo = 0;
  private maxCombo = 0;
  private comboExpireAt = 0;
  private catches: RunFishCatch[] = [];
  private maxDepth = 0;
  private notifiedDepth = 0;
  private currentZoneId = '';
  private elapsedMs = 0;
  private caughtFish: FishEntity | null = null;
  private caughtAtDepth = 0;
  /** How long the line has been slack during a fight (drives ESCAPE, §18). */
  private slackMs = 0;

  constructor(options: EngineOptions) {
    this.config = options.config;
    this.loadout = options.loadout ?? DEFAULT_LOADOUT;
    this.rng = new Rng(options.seed ?? 1);
    this.onStateChange = options.onStateChange;
    this.onEvent = options.onEvent;
    this.currentZoneId = this.zoneAt(0)?.id ?? '';
  }

  // ---- Public API ------------------------------------------------------------

  start(): void {
    if (this.state !== 'READY' && this.state !== 'RESULTS') return;
    if (this.state === 'RESULTS') this.resetRun();
    this.setState('PLAYING');
    this.hookState = 'DESCENDING';
  }

  /** Full run reset so Play Again starts a fresh dive from the surface. */
  private resetRun(): void {
    // Silent reset — the public setState('PLAYING') below is the single notification.
    this.state = 'READY';
    this.hookState = 'READY';
    this.hookX = 0;
    this.inputX = 0;
    this.hookDepth = 0;
    this.tension = 0;
    this.reeling = false;
    this.brokenUntil = 0;
    this.hitInvulnUntil = 0;
    this.dangerUntil = 0;
    this.fish = [];
    this.spawnTimer = 0.5;
    this.score = 0;
    this.credits = 0;
    this.combo = 0;
    this.maxCombo = 0;
    this.comboExpireAt = 0;
    this.catches = [];
    this.maxDepth = 0;
    this.notifiedDepth = 0;
    this.currentZoneId = this.zoneAt(0)?.id ?? '';
    this.elapsedMs = 0;
    this.caughtFish = null;
    this.caughtAtDepth = 0;
    this.slackMs = 0;
  }

  pause(): void {
    if (this.state === 'PLAYING') this.setState('PAUSED');
  }

  resume(): void {
    if (this.state === 'PAUSED') this.setState('PLAYING');
  }

  /** Horizontal input in [-1, 1]. Touch drag, mouse and keys all map here. */
  setInput(input: number): void {
    this.inputX = Math.max(-1, Math.min(1, input));
  }

  reel(): void {
    this.reeling = true;
  }

  /** Hot-apply an upgrade loadout (economy purchases, §60). Takes effect next run. */
  setLoadout(loadout: PlayerLoadout): void {
    this.loadout = { ...loadout };
  }

  stopReel(): void {
    this.reeling = false;
  }

  get elapsed(): number {
    return this.elapsedMs;
  }

  getState(): GameState {
    return this.state;
  }

  getHook(): HookSnapshot {
    return {
      x: this.hookX,
      depth: this.hookDepth,
      state: this.hookState,
      tensionRatio: Math.min(1, this.tension / this.tensionLimit()),
      hookedFishId: this.caughtFish?.species.id ?? null,
    };
  }

  getFish(): FishSnapshot[] {
    return this.fish.map((f) => ({
      entityId: f.entityId,
      speciesId: f.species.id,
      x: f.x,
      depth: f.depth,
      facing: f.facing,
      danger: f.species.danger,
      rarity: f.species.rarity,
      hooked: f.hooked,
    }));
  }

  getStats(): EngineStats {
    return {
      score: this.score,
      catches: this.catches.length,
      maxCombo: this.maxCombo,
      maxDepth: this.maxDepth,
      elapsedMs: this.elapsedMs,
      provisionalCredits: Math.floor(this.credits),
    };
  }

  getCatches(): RunFishCatch[] {
    return this.catches.map((c) => ({ ...c }));
  }

  getSnapshot(): RunSnapshot {
    return {
      state: this.state,
      hook: this.getHook(),
      fish: this.getFish(),
      score: this.score,
      combo: this.combo,
      comboMultiplier: this.comboMultiplier(),
      provisionalCredits: Math.floor(this.credits),
      catches: this.catches.length,
      elapsedMs: this.elapsedMs,
      maxDepth: this.maxDepth,
    };
  }

  /** Advance the simulation by dtSeconds (clamped). */
  update(dtSeconds: number): void {
    const dt = Math.min(dtSeconds, 0.1);
    if (this.state === 'DANGER' && this.elapsedMs >= this.dangerUntil) {
      this.setState('PLAYING');
    }
    if (this.state !== 'PLAYING' && this.state !== 'DANGER') return;

    this.elapsedMs += dt * 1000;
    this.updateHook(dt);
    this.updateFish(dt);
    this.updateSpawning(dt);
    this.updateCollisions();
    this.updateComboExpiry();
    this.clampHook();
    this.checkDepthEvents();
  }

  // ---- Hook ------------------------------------------------------------------

  private updateHook(dt: number): void {
    const speedFactor = this.hookState === 'CAUGHT' ? 0.5 : 1;
    this.hookX += this.inputX * HOOK_MOVE_SPEED * speedFactor * dt;

    switch (this.hookState) {
      case 'DESCENDING': {
        this.hookDepth += this.config.economy.hookDescendSpeed * dt;
        if (this.hookDepth >= this.lineLength()) {
          this.hookState = 'RETRACTING';
        }
        break;
      }
      case 'CAUGHT': {
        this.fightCaughtFish(dt);
        break;
      }
      case 'ESCAPING':
      case 'BROKEN': {
        // §18: a lost fish is a setback, not a run-ender — resume the dive.
        if (this.elapsedMs >= this.brokenUntil) this.hookState = 'DESCENDING';
        break;
      }
      case 'RETRACTING': {
        this.hookDepth -= this.reelSpeed() * dt;
        this.tension = Math.max(0, this.tension - TENSION_DECAY * dt);
        if (this.hookDepth <= 0) {
          this.endRun('surface');
        }
        break;
      }
      case 'READY':
      case 'CONTACT':
        break;
    }
  }

  private fightCaughtFish(dt: number): void {
    const f = this.caughtFish;
    if (!f) {
      this.hookState = 'RETRACTING';
      return;
    }
    const struggle =
      f.species.weight * TENSION_PER_WEIGHT + Math.abs(f.vX) * TENSION_PER_SPEED;

    // §18/§19 fight model: "stamina reel-off". Reeling drains the fish's
    // stamina in place (tension rises); resting lets tension fall but the fish
    // recovers a little. Win the reel-off → landed catch at your depth.
    if (this.reeling) {
      this.tension = Math.max(0, this.tension + (struggle * 0.35 - TENSION_DECAY) * dt);
      f.stamina -= dt;
      this.slackMs = 0;
    } else {
      this.tension = Math.max(0, this.tension + (struggle * 0.1 - TENSION_DECAY) * dt);
      f.stamina = Math.min(f.stamina + dt * 0.35, f.species.weight * 14 + 4);
      // Slack line: the fish eventually throws the hook (§18 ESCAPING).
      this.slackMs += dt * 1000;
      if (this.slackMs > 2200 + f.species.weight * 1500) {
        this.slackMs = 0;
        this.escapeCaught(f);
        return;
      }
    }

    if (f.stamina <= 0) {
      this.landCatch(f);
      return;
    }
    // The hook hangs in the fish's mouth: it follows the fight.
    this.hookDepth = f.depth;

    if (this.tension >= this.tensionLimit()) {
      this.breakLine(f);
      return;
    }
    // Landing is stamina-driven now (stamina <= 0 above) — no surface tow needed.
  }

  private escapeCaught(f: FishEntity): void {
    f.hooked = false;
    f.vX = f.facing * f.species.speed * 1.6;
    this.caughtFish = null;
    this.tension = 0;
    this.combo = 0;
    this.hookState = 'ESCAPING';
    this.brokenUntil = this.elapsedMs + 600;
    // Invulnerable window so the hook can descend past the escaped fish
    // instead of re-colliding with it every frame (§18).
    this.hitInvulnUntil = this.elapsedMs + 1000;
    this.emit({ kind: 'ESCAPE', atMs: this.elapsedMs, data: { fishId: f.species.id } });
  }

  private breakLine(f: FishEntity): void {
    f.hooked = false;
    f.vX = f.facing * f.species.speed * 1.5;
    this.caughtFish = null;
    this.tension = 0;
    this.combo = 0;
    this.hookState = 'BROKEN';
    this.brokenUntil = this.elapsedMs + DANGER_MS;
    this.enterDanger();
    this.emit({ kind: 'LINE_BREAK', atMs: this.elapsedMs, data: { fishId: f.species.id } });
  }

  private enterDanger(): void {
    this.dangerUntil = this.elapsedMs + DANGER_MS;
    this.hitInvulnUntil = this.elapsedMs + HIT_INVULN_MS;
    this.setState('DANGER');
  }

  private landCatch(f: FishEntity): void {
    const mult = this.comboMultiplier();
    const gainedScore = Math.round(f.species.score * mult);
    this.score += gainedScore;
    this.credits += f.species.creditReward * mult;
    this.combo += 1;
    this.maxCombo = Math.max(this.maxCombo, this.combo);
    this.comboExpireAt = this.elapsedMs + this.config.economy.comboWindowsMs;
    this.catches.push({ fishId: f.species.id, depth: Math.round(this.caughtAtDepth), atMs: Math.round(this.elapsedMs) });
    this.emit({
      kind: 'CATCH',
      atMs: this.elapsedMs,
      data: { fishId: f.species.id, score: gainedScore, combo: this.combo, multiplier: mult },
    });
    if (this.combo >= 2) {
      this.emit({ kind: 'COMBO_UP', atMs: this.elapsedMs, data: { combo: this.combo, multiplier: mult } });
    }
    this.removeFish(f);
    this.caughtFish = null;
    this.tension = 0;
    this.hookState = 'DESCENDING';
  }

  private comboMultiplier(): number {
    const tiers = this.config.economy.comboMultipliers;
    const idx = Math.min(this.combo, tiers.length - 1);
    return tiers[idx] ?? 1;
  }

  private updateComboExpiry(): void {
    if (this.combo > 0 && this.elapsedMs > this.comboExpireAt) {
      this.combo = 0;
    }
  }

  private lineLength(): number {
    // Baseline 260m (config), +45m per line_length upgrade level (§19 balance).
    const base = this.config.economy.baselineLineLengthM ?? 260;
    return base + this.loadout.lineLength * 45;
  }

  private reelSpeed(): number {
    return REEL_BASE_SPEED + this.loadout.reelSpeed * 6;
  }

  private tensionLimit(): number {
    return this.config.economy.lineTensionLimit * (1 + this.loadout.lineStrength * 0.25);
  }

  // ---- Fish ------------------------------------------------------------------

  private updateFish(dt: number): void {
    for (const f of this.fish) {
      if (f.hooked) continue;
      this.applyBehavior(f, dt);

      f.x += f.vX * dt;
      f.depth += f.vDepth * dt;

      if (f.x > WORLD_HALF_WIDTH) {
        f.x = WORLD_HALF_WIDTH;
        f.vX = -Math.abs(f.vX);
      } else if (f.x < -WORLD_HALF_WIDTH) {
        f.x = -WORLD_HALF_WIDTH;
        f.vX = Math.abs(f.vX);
      }
      if (f.vX !== 0) f.facing = f.vX > 0 ? 1 : -1;

      const band = this.speciesBand(f.species);
      if (f.depth < band.min) {
        f.depth = band.min;
        f.vDepth = Math.abs(f.vDepth);
      } else if (f.depth > band.max) {
        f.depth = band.max;
        f.vDepth = -Math.abs(f.vDepth);
      }
    }

    // Despawn fish far behind the hook.
    this.fish = this.fish.filter((f) => f.hooked || f.depth > this.hookDepth - 45);
  }

  private applyBehavior(f: FishEntity, dt: number): void {
    const hookDx = this.hookX - f.x;
    const hookDd = this.hookDepth - f.depth;
    const dist = Math.hypot(hookDx, hookDd * 0.6);

    switch (f.species.behavior) {
      case 'SLOW': {
        if (this.elapsedMs >= f.nextTurnAt) {
          f.nextTurnAt = this.elapsedMs + this.rng.range(2000, 4500);
          f.vDepth = this.rng.range(-3, 3);
        }
        break;
      }
      case 'FAST': {
        if (this.elapsedMs >= f.nextTurnAt) {
          f.nextTurnAt = this.elapsedMs + this.rng.range(1200, 2200);
          f.vX *= this.rng.next() < 0.4 ? -1 : 1;
          f.vDepth = this.rng.range(-6, 6);
        }
        break;
      }
      case 'FLEE': {
        if (dist < FLEE_RADIUS) {
          f.vX = -Math.sign(hookDx) * f.species.speed * 1.3;
          f.vDepth = -Math.sign(hookDd) * f.species.speed * 0.4;
        } else if (this.elapsedMs >= f.nextTurnAt) {
          f.nextTurnAt = this.elapsedMs + this.rng.range(1800, 3600);
          f.vDepth = this.rng.range(-4, 4);
        }
        break;
      }
      case 'ZIGZAG': {
        if (this.elapsedMs >= f.nextTurnAt) {
          f.nextTurnAt = this.elapsedMs + this.rng.range(350, 700);
          f.vX = f.facing * -1 * f.species.speed;
          f.vDepth = this.rng.range(-8, 8);
        }
        break;
      }
      case 'HEAVY': {
        f.vDepth = 5 + f.species.weight * 6;
        break;
      }
      case 'PREDATOR': {
        if (dist < CHASE_RADIUS) {
          f.vX = Math.sign(hookDx) * f.species.speed * 1.2;
          f.vDepth = Math.sign(hookDd) * f.species.speed * 0.6;
        } else if (this.elapsedMs >= f.nextTurnAt) {
          f.nextTurnAt = this.elapsedMs + this.rng.range(1500, 3000);
          f.vDepth = this.rng.range(-5, 5);
        }
        break;
      }
      case 'SHARK': {
        if (this.elapsedMs < f.nextTurnAt) {
          // Knocked through recently: keep leaving, don't re-chase (§24 fairness).
        } else if (dist < CHASE_RADIUS * 1.4) {
          f.vX = Math.sign(hookDx) * f.species.speed * 1.35;
          f.vDepth = Math.sign(hookDd) * f.species.speed * 0.5;
        } else if (this.elapsedMs >= f.nextTurnAt) {
          f.nextTurnAt = this.elapsedMs + this.rng.range(2200, 3800);
          f.vX = (this.rng.next() < 0.5 ? -1 : 1) * f.species.speed * 0.6;
          f.vDepth = this.rng.range(-4, 4);
        }
        break;
      }
      case 'LEGENDARY': {
        if (this.elapsedMs >= f.nextTurnAt) {
          f.nextTurnAt = this.elapsedMs + this.rng.range(400, 900);
          f.vX = (this.rng.next() < 0.55 ? -1 : 1) * f.species.speed * (this.rng.next() < 0.3 ? 1.6 : 1);
          f.vDepth = this.rng.range(-10, 10);
        }
        break;
      }
    }
  }

  private updateSpawning(dt: number): void {
    this.spawnTimer -= dt;
    if (this.spawnTimer > 0 || this.fish.length >= MAX_FISH) return;
    this.spawnTimer = SPAWN_BASE_S * this.rng.range(0.7, 1.3);
    const species = this.pickSpecies();
    if (!species) return;
    this.spawnFish(species);
  }

  private pickSpecies(): FishSpeciesDef | null {
    const pool = this.config.fish.filter(
      (f) => this.hookDepth >= f.depthMin - 10 && this.hookDepth <= f.depthMax + 10,
    );
    if (pool.length === 0) return null;
    const weights = pool.map((f) => {
      let w = FISHKAL_RARITY_WEIGHTS[f.rarity];
      if (f.behavior === 'SHARK' && this.hookDepth < 80) w *= 0.2;
      if (f.rarity === 'LEGENDARY') {
        w *= this.hookDepth >= 300 && this.rng.next() < 0.25 ? 1 : 0;
      }
      return w;
    });
    const total = weights.reduce((a, b) => a + b, 0);
    if (total <= 0) return null;
    let roll = this.rng.next() * total;
    for (let i = 0; i < pool.length; i++) {
      roll -= weights[i] ?? 0;
      if (roll <= 0) return pool[i] ?? null;
    }
    return pool[pool.length - 1] ?? null;
  }

  private spawnFish(species: FishSpeciesDef): void {
    const fromLeft = this.rng.next() < 0.5;
    const band = this.speciesBand(species);
    const entity: FishEntity = {
      entityId: this.nextEntityId++,
      species,
      x: fromLeft ? -WORLD_HALF_WIDTH - 2 : WORLD_HALF_WIDTH + 2,
      depth: Math.max(band.min, Math.min(band.max, this.hookDepth + this.rng.range(-8, 12))),
      vX: (fromLeft ? 1 : -1) * species.speed,
      vDepth: 0,
      facing: fromLeft ? 1 : -1,
      hooked: false,
      nextTurnAt: this.elapsedMs + this.rng.range(500, 2000),
      stamina: 0,
    };
    this.fish.push(entity);
  }

  private removeFish(target: FishEntity): void {
    this.fish = this.fish.filter((f) => f !== target);
  }

  private speciesBand(s: FishSpeciesDef): { min: number; max: number } {
    return { min: s.depthMin, max: Math.max(s.depthMax, s.depthMin + 10) };
  }

  // ---- Collisions ------------------------------------------------------------

  private updateCollisions(): void {
    if (this.hookState !== 'DESCENDING') return;
    if (this.elapsedMs < this.hitInvulnUntil) return;

    for (const f of this.fish) {
      if (f.hooked) continue;
      const hitR = HOOK_HALF + f.species.size * 0.5;
      if (Math.abs(this.hookX - f.x) < hitR && Math.abs(this.hookDepth - f.depth) < hitR) {
        if (f.species.danger) {
          this.dangerHit(f);
        } else {
          this.tryAttach(f);
        }
        return;
      }
    }
  }

  private tryAttach(f: FishEntity): void {
    const p = this.catchProbability(f);
    if (this.rng.next() < p) {
      f.hooked = true;
      this.caughtFish = f;
      this.caughtAtDepth = f.depth;
      this.hookState = 'CAUGHT';
      this.tension = f.species.weight * 30;
      // Stamina = reel-seconds needed to land it (heavier = longer fight, §19).
      f.stamina = f.species.weight * 14 + 4;
    } else {
      this.hookState = 'ESCAPING';
      this.brokenUntil = this.elapsedMs + 300;
      this.hitInvulnUntil = this.elapsedMs + 800;
      f.vX = f.facing * f.species.speed * 1.8;
      this.emit({ kind: 'ESCAPE', atMs: this.elapsedMs, data: { fishId: f.species.id } });
    }
  }

  private catchProbability(f: FishEntity): number {
    const p =
      CATCH_BASE[f.species.rarity] -
      f.species.weight * 0.3 +
      this.loadout.hookStrength * 0.04;
    return Math.max(0.1, Math.min(0.95, p));
  }

  private dangerHit(f: FishEntity): void {
    // §24 danger: threatens line tension and combo — it never erases score.
    this.combo = 0;
    this.tension = Math.min(this.tensionLimit() * 0.9, this.tension + 30 + f.species.weight * 40);
    // Knock the predator through and past — no perma-camping on the hook.
    f.vX = Math.sign(f.x - this.hookX || 1) * f.species.speed * 2.2;
    f.vDepth = Math.sign(f.depth - this.hookDepth) * f.species.speed * 0.6;
    f.nextTurnAt = this.elapsedMs + 2500;
    this.enterDanger();
    this.emit({ kind: 'SHARK_HIT', atMs: this.elapsedMs, data: { fishId: f.species.id } });
  }

  // ---- World -----------------------------------------------------------------

  private clampHook(): void {
    this.hookX = Math.max(-WORLD_HALF_WIDTH, Math.min(WORLD_HALF_WIDTH, this.hookX));
    if (this.hookDepth < 0) this.hookDepth = 0;
  }

  private zoneAt(depth: number) {
    return (
      this.config.depthZones.find((z) => depth >= z.depthMin && depth < z.depthMax) ??
      this.config.depthZones[this.config.depthZones.length - 1]
    );
  }

  private checkDepthEvents(): void {
    if (this.hookDepth > this.maxDepth) {
      this.maxDepth = this.hookDepth;
      if (this.maxDepth - this.notifiedDepth >= 50) {
        this.notifiedDepth = this.maxDepth;
        this.emit({ kind: 'MAX_DEPTH', atMs: this.elapsedMs, data: { depth: Math.round(this.maxDepth) } });
      }
    }
    const zone = this.zoneAt(this.hookDepth);
    if (zone && zone.id !== this.currentZoneId) {
      this.currentZoneId = zone.id;
      this.emit({ kind: 'DEPTH_ZONE', atMs: this.elapsedMs, data: { zone: zone.id, name: zone.name } });
    }
  }

  private endRun(reason: string): void {
    this.hookState = 'READY';
    this.setState('RESULTS');
    this.emit({ kind: 'RUN_END', atMs: this.elapsedMs, data: { reason } });
  }

  private setState(s: GameState): void {
    this.state = s;
    this.onStateChange?.(s);
  }

  private emit(event: GameEvent): void {
    this.onEvent?.(event);
  }
}

export type { HookState } from './state.js';

export { FishkalEngine } from './engine.js';
export type { EngineOptions, EngineStats } from './engine.js';
export { Rng } from './rng.js';
export * from './state.js';

/** Deterministic seeded RNG so runs are reproducible for server-side checks. */
export class Rng {
  private state: number;

  constructor(seed: number) {
    this.state = seed >>> 0;
  }

  /** mulberry32 — returns float in [0, 1). */
  next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  range(min: number, max: number): number {
    return min + this.next() * (max - min);
  }

  pick<T>(items: readonly T[]): T {
    const idx = Math.floor(this.next() * items.length);
    const item = items[idx];
    if (item === undefined) throw new Error('Rng.pick on empty list');
    return item;
  }
}

/** Game state machine (spec §28) and hook states (spec §18). Engine-agnostic. */

export type GameState =
  | 'LOADING'
  | 'READY'
  | 'PLAYING'
  | 'PAUSED'
  | 'CATCHING'
  | 'DANGER'
  | 'GAME_OVER'
  | 'RESULTS';

export type HookState =
  | 'READY'
  | 'DESCENDING'
  | 'CONTACT'
  | 'CAUGHT'
  | 'ESCAPING'
  | 'RETRACTING'
  | 'BROKEN';

export type GameEventKind =
  | 'CATCH'
  | 'ESCAPE'
  | 'LINE_BREAK'
  | 'SHARK_HIT'
  | 'COMBO_UP'
  | 'DEPTH_ZONE'
  | 'MAX_DEPTH'
  | 'RUN_END';

export interface GameEvent {
  kind: GameEventKind;
  atMs: number;
  /** Optional payload (fishId, zone name, combo level…). */
  data?: Record<string, unknown>;
}

export interface HookSnapshot {
  x: number;
  depth: number;
  state: HookState;
  tensionRatio: number;
  hookedFishId: string | null;
}

export interface FishSnapshot {
  entityId: number;
  speciesId: string;
  x: number;
  depth: number;
  facing: -1 | 1;
  danger: boolean;
  rarity: string;
  hooked: boolean;
}

export interface RunSnapshot {
  state: GameState;
  hook: HookSnapshot;
  fish: FishSnapshot[];
  score: number;
  combo: number;
  comboMultiplier: number;
  provisionalCredits: number;
  catches: number;
  elapsedMs: number;
  maxDepth: number;
}

/** Upgrade levels owned by the player (0-based). Costs are handled outside the engine. */
export interface PlayerLoadout {
  hookStrength: number;
  lineStrength: number;
  lineLength: number;
  reelSpeed: number;
  magnetRadius: number;
}

export const DEFAULT_LOADOUT: PlayerLoadout = {
  hookStrength: 0,
  lineStrength: 0,
  lineLength: 0,
  reelSpeed: 0,
  magnetRadius: 0,
};

/**
 * WebGL cinematic intro (spec §03, roadmap 4d) — "Dubai → boat → dive" mood
 * piece that plays over the hero section. Pure three.js, zero asset downloads:
 * boat from boxes (hull + cabin + mast), sun light, ~600 drifting particles
 * whose color shifts through the four depth zones into abyssal dark.
 * Swap point for the future HDRI + GLB boat (assets/README.md).
 */
import * as THREE from 'three';

export class CinematicIntro {
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera: THREE.PerspectiveCamera;
  private boat = new THREE.Group();
  private particles: THREE.Points;
  private raf = 0;
  private disposed = false;
  private t = 0;
  private readonly clock = new THREE.Clock();

  constructor(private canvas: HTMLCanvasElement) {
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    this.renderer.setClearColor(0x000000, 0);
    this.camera = new THREE.PerspectiveCamera(55, 1, 0.1, 400);

    // Sky-to-ocean backdrop: brand navy sky, deep water below the camera path.
    this.scene.background = new THREE.Color('#0D3B66');
    this.scene.fog = new THREE.FogExp2('#0D3B66', 0.008);

    // Sun + ambient.
    const sun = new THREE.DirectionalLight('#FFE7C4', 2.2);
    sun.position.set(6, 10, 4);
    this.scene.add(sun, new THREE.AmbientLight('#7FB7D9', 0.55));

    // Water surface plane with a gentle shader-free shimmer (vertex waves).
    const surfaceGeo = new THREE.PlaneGeometry(400, 400, 40, 40);
    const surface = new THREE.Mesh(
      surfaceGeo,
      new THREE.MeshStandardMaterial({ color: '#14607F', transparent: true, opacity: 0.55, roughness: 0.25, metalness: 0.1 }),
    );
    surface.rotation.x = -Math.PI / 2;
    surface.position.y = 0;
    this.scene.add(surface);
    this.surface = surface;

    // Procedural boat.
    const hullMat = new THREE.MeshStandardMaterial({ color: '#F4EFE6', roughness: 0.6 });
    const deckMat = new THREE.MeshStandardMaterial({ color: '#C9A66B', roughness: 0.7 });
    const hull = new THREE.Mesh(new THREE.BoxGeometry(6, 1.2, 2.2), hullMat);
    const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.8, 1.1, 1.6), deckMat);
    cabin.position.set(-1.2, 1.1, 0);
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 4), deckMat);
    mast.position.set(1.4, 2.4, 0);
    const flag = new THREE.Mesh(
      new THREE.PlaneGeometry(1.1, 0.65),
      new THREE.MeshStandardMaterial({ color: '#10B6A8', side: THREE.DoubleSide }),
    );
    flag.position.set(1.95, 3.9, 0);
    this.boat.add(hull, cabin, mast, flag);
    this.boat.position.set(0, 0.55, 0);
    this.scene.add(this.boat);

    // Drifting particles (plankton/sediment) below the surface.
    const N = 600;
    const pos = new Float32Array(N * 3);
    for (let i = 0; i < N; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 90;
      pos[i * 3 + 1] = -Math.random() * 120;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 90;
    }
    const pgeo = new THREE.BufferGeometry();
    pgeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.particles = new THREE.Points(
      pgeo,
      new THREE.PointsMaterial({ color: '#9FD8D0', size: 0.28, transparent: true, opacity: 0.65, sizeAttenuation: true }),
    );
    this.scene.add(this.particles);

    this.scene.add(new THREE.HemisphereLight('#8FD3E8', '#0B1B26', 0.4));

    this.resize();
    window.addEventListener('resize', this.resize);
    this.loop();
  }

  private surface: THREE.Mesh;

  private resize = (): void => {
    const w = this.canvas.clientWidth || 1;
    const h = this.canvas.clientHeight || 1;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  };

  private loop = (): void => {
    if (this.disposed) return;
    this.raf = requestAnimationFrame(this.loop);
    const dt = Math.min(this.clock.getDelta(), 0.1);
    this.t += dt;

    // Camera: hover by the boat, then slowly descend into the deep (loops).
    const cycle = (this.t % 36) / 36; // 36s cinematic loop
    const descend = THREE.MathUtils.smoothstep(cycle, 0.12, 0.75);
    const depthY = -THREE.MathUtils.lerp(2, 110, descend);
    this.camera.position.set(9 - 6 * descend, depthY, 10 - 4 * descend);
    this.camera.lookAt(descend > 0.5 ? new THREE.Vector3(0, depthY - 14, -8) : this.boat.position);

    // Boat bobbing.
    this.boat.position.y = 0.55 + Math.sin(this.t * 1.1) * 0.22;
    this.boat.rotation.z = Math.sin(this.t * 0.9) * 0.045;
    this.boat.rotation.x = Math.cos(this.t * 0.7) * 0.03;

    // Gentle surface waves + particle drift.
    const pos = this.surface.geometry.attributes.position as THREE.BufferAttribute;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const y = pos.getY(i);
      pos.setZ(i, Math.sin(x * 0.12 + this.t * 1.4) * 0.35 + Math.cos(y * 0.1 + this.t) * 0.25);
    }
    pos.needsUpdate = true;

    const pp = this.particles.geometry.attributes.position as THREE.BufferAttribute;
    for (let i = 0; i < pp.count; i++) {
      let y = pp.getY(i) - dt * 0.7;
      if (y < -125) y = 0;
      pp.setY(i, y);
    }
    pp.needsUpdate = true;

    // Zone tint: turquoise shelf → blue → deep navy → abyss (§16).
    const zones = ['#14607F', '#1B7A8C', '#0B3550', '#04121F'];
    const idx = Math.min(3, Math.floor(descend * 4));
    const next = zones[Math.min(3, idx + 1)];
    const frac = THREE.MathUtils.clamp(descend * 4 - idx, 0, 1);
    const col = new THREE.Color(zones[idx]).lerp(new THREE.Color(next), frac);
    (this.scene.fog as THREE.FogExp2).color.copy(col);
    this.renderer.setClearColor(col, this.renderer.getClearAlpha());

    this.renderer.render(this.scene, this.camera);
  };

  dispose(): void {
    this.disposed = true;
    cancelAnimationFrame(this.raf);
    window.removeEventListener('resize', this.resize);
    this.scene.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (mesh.geometry) mesh.geometry.dispose();
      const mat = mesh.material as THREE.Material | THREE.Material[] | undefined;
      if (Array.isArray(mat)) mat.forEach((m) => m.dispose());
      else mat?.dispose();
    });
    this.renderer.dispose();
  }
}

import * as THREE from 'three';
import type { FishSpeciesDef, Rarity } from '@fishkal/shared';

/** Rarity → visual treatment (spec §14). Legendary gets gold + emissive pulse. */
export const RARITY_COLORS: Record<Rarity, number> = {
  COMMON: 0x9fb4c4,
  UNCOMMON: 0x4fb286,
  RARE: 0x3e8ed0,
  EPIC: 0x9b5de5,
  LEGENDARY: 0xe8b84b,
};

/**
 * Procedural low-poly fish: stretched icosahedron body + tail fin.
 * Zero downloads; species differ by scale, color, and tail rate (spec §103 allows
 * tracked procedural placeholders until production GLBs replace them — ASSET_REQUIRED).
 */
export class FishMeshFactory {
  private bodyGeo = new THREE.IcosahedronGeometry(0.5, 1);
  private tailGeo = new THREE.ConeGeometry(0.28, 0.55, 4);

  create(species: FishSpeciesDef): THREE.Group {
    const color = RARITY_COLORS[species.rarity];
    const emissive = species.rarity === 'LEGENDARY' || species.rarity === 'EPIC';
    const material = new THREE.MeshStandardMaterial({
      color,
      roughness: 0.45,
      metalness: 0.15,
      emissive: emissive ? color : 0x000000,
      emissiveIntensity: emissive ? 0.35 : 0,
    });

    const group = new THREE.Group();

    const body = new THREE.Mesh(this.bodyGeo, material);
    body.scale.set(1.5, 0.75, 0.45);
    group.add(body);

    const tail = new THREE.Mesh(this.tailGeo, material);
    tail.rotation.z = Math.PI / 2;
    tail.position.x = -0.85;
    group.add(tail);
    group.userData.tail = tail;

    if (species.danger) {
      // Dorsal fin to read as "shark/danger" silhouette.
      const fin = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.5, 4), material);
      fin.position.set(0.1, 0.45, 0);
      group.add(fin);
    }

    const s = species.size;
    group.scale.setScalar(s);
    return group;
  }

  animateTail(group: THREE.Group, timeMs: number, speed: number): void {
    const tail = group.userData.tail as THREE.Mesh | undefined;
    if (tail) {
      tail.rotation.y = Math.sin(timeMs * 0.012 * speed) * 0.5;
    }
  }

  dispose(): void {
    this.bodyGeo.dispose();
    this.tailGeo.dispose();
  }
}

import * as THREE from 'three';
import { FishkalEngine } from '@fishkal/game-core';
import type { GameConfig } from '@fishkal/config';
import type { PlayerLoadout, RunSnapshot } from '@fishkal/game-core';
import { FishMeshFactory, RARITY_COLORS } from './fish.js';
import { GlbFishFactory } from './glb-fish.js';
import { createHook, FishingLine } from './hooks.js';
import { createOceanSurface, createUnderwaterAtmosphere } from './ocean.js';
import { Sfx } from './sfx.js';
import type { SfxName } from './sfx.js';

export interface GameViewOptions {
  container: HTMLElement;
  config: GameConfig;
  loadout?: PlayerLoadout;
  seed?: number;
  onStateChange?: (state: string) => void;
  onEvent?: (kind: string, data?: Record<string, unknown>) => void;
  onResults?: (stats: { score: number; catches: number; maxCombo: number; maxDepth: number; elapsedMs: number; provisionalCredits: number }) => void;
}

/** Performance profile (spec §89) — can be switched at runtime. */
export type PerfMode = 'AUTO' | 'HIGH' | 'BALANCED' | 'LOW';

const PERF_SETTINGS: Record<PerfMode, { particles: number; pixelRatioCap: number }> = {
  AUTO: { particles: 600, pixelRatioCap: 2 },
  HIGH: { particles: 900, pixelRatioCap: 2 },
  BALANCED: { particles: 400, pixelRatioCap: 1.5 },
  LOW: { particles: 150, pixelRatioCap: 1 },
};

/** Renders the Deep Catch game around the engine; UI (HUD/menus) stays in React. */
export class GameView {
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera: THREE.PerspectiveCamera;
  private engine: FishkalEngine;
  private factory = new FishMeshFactory();
  private line: FishingLine;
  private hookGroup: THREE.Group;
  private atmosphere: ReturnType<typeof createUnderwaterAtmosphere>;
  private fishViews = new Map<number, { group: THREE.Group; speciesId: string; fromGlb: boolean }>();
  private raf = 0;
  private lastTime = 0;
  private acc = 0;
  private running = false;
  private container: HTMLElement;
  private perfMode: PerfMode = 'AUTO';
  /** Procedural SFX (roadmap 2.4) — swap with CC0 samples later via Sfx. */
  readonly sfx = new Sfx();
  /** GLB fish pipeline (roadmap 2.3/2.6) — falls back to procedural per species. */
  readonly glbFish = new GlbFishFactory();

  constructor(private options: GameViewOptions) {
    const container = options.container;
    this.container = container;

    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.setSize(container.clientWidth, container.clientHeight);
    container.appendChild(this.renderer.domElement);

    this.camera = new THREE.PerspectiveCamera(58, container.clientWidth / container.clientHeight, 0.1, 600);

    this.scene.fog = new THREE.FogExp2(0x1b7a8c, 0.014);
    this.scene.background = new THREE.Color(0x0d3b66);

    // Lighting: dim sun + caustic fill.
    this.scene.add(new THREE.HemisphereLight(0xbfe8e2, 0x072540, 0.9));
    const sun = new THREE.DirectionalLight(0xfff3d6, 1.1);
    sun.position.set(6, 40, 8);
    this.scene.add(sun);

    const ocean = createOceanSurface();
    ocean.position.y = 0;
    this.scene.add(ocean);

    this.atmosphere = createUnderwaterAtmosphere(this.scene);

    this.hookGroup = createHook();
    this.scene.add(this.hookGroup);
    this.line = new FishingLine();
    this.scene.add(this.line.mesh);

    this.engine = new FishkalEngine({
      config: options.config,
      loadout: options.loadout,
      seed: options.seed,
      onStateChange: (s) => options.onStateChange?.(s),
      onEvent: (e) => {
        this.playEventSfx(e.kind);
        options.onEvent?.(e.kind, e.data);
      },
    });

    window.addEventListener('resize', this.onResize);
    this.bindInput();

    // Prefetch production fish GLBs if present (no-op when assets not yet added).
    const modelBase = (import.meta as unknown as { env?: Record<string, string> }).env?.PUBLIC_URL ?? '';
    this.glbFish.prefetch(
      options.config.fish.map((f) => f.id),
      [`${modelBase}/models`, '/models'],
    );
  }

  /** Map engine events to sounds; unknown kinds stay silent. */
  /** Hot-replace the player's upgrade loadout (applies on the next run). */
  applyLoadout(loadout: PlayerLoadout): void {
    this.engine.setLoadout(loadout);
  }

  private playEventSfx(kind: string): void {
    const map: Record<string, SfxName> = {
      CATCH: 'catch',
      ESCAPE: 'escape',
      LINE_BREAK: 'line_break',
      SHARK_HIT: 'danger',
      DEPTH_ZONE: 'depth_zone',
    };
    const name = map[kind];
    if (name) this.sfx.play(name);
  }

  private onResize = (): void => {
    const w = this.container.clientWidth;
    const h = this.container.clientHeight;
    if (w === 0 || h === 0) return;
    this.renderer.setSize(w, h);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  };

  // ---- Public API ------------------------------------------------------------

  startGame(): void {
    this.sfx.resume(); // user gesture — unlock audio
    this.engine.start();
    this.running = true;
    this.lastTime = performance.now();
    if (!this.raf) this.raf = requestAnimationFrame(this.tick);
    this.sfx.play('splash');
  }

  setPerfMode(mode: PerfMode): void {
    this.perfMode = mode;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, PERF_SETTINGS[mode].pixelRatioCap));
  }

  dispose(): void {
    this.running = false;
    cancelAnimationFrame(this.raf);
    window.removeEventListener('resize', this.onResize);
    this.unbindInput();
    this.atmosphere.dispose();
    this.factory.dispose();
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }

  getEngine(): FishkalEngine {
    return this.engine;
  }

  // ---- Internals -------------------------------------------------------------

  private tick = (now: number): void => {
    this.raf = requestAnimationFrame(this.tick);
    const frameMs = Math.min(now - this.lastTime, 100);
    this.lastTime = now;
    if (!this.running) return;

    // Fixed-timestep accumulation (spec §27: simulation separate from rendering).
    this.acc += frameMs / 1000;
    const DT = 1 / 60;
    while (this.acc >= DT) {
      this.engine.update(DT);
      this.acc -= DT;
    }

    this.syncScene();
    this.atmosphere.update(now, this.engine.getHook().depth);
    this.renderer.render(this.scene, this.camera);

    if (this.engine.getState() === 'RESULTS' && this.options.onResults) {
      this.running = false;
      const stats = this.engine.getStats();
      this.options.onResults(stats);
    }
  };

  private syncScene(): void {
    const snap = this.engine.getSnapshot();
    this.syncFish(snap);
    this.syncHook(snap);
    this.syncCamera(snap.hook.depth);
  }

  private syncFish(snap: RunSnapshot): void {
    const seen = new Set<number>();
    for (const f of snap.fish) {
      seen.add(f.entityId);
      let view = this.fishViews.get(f.entityId);
      if (!view) {
        const species = this.options.config.fish.find((s) => s.id === f.speciesId);
        if (!species) continue;
        // GLB when cached (2.6), procedural fallback otherwise — never break.
        const model = this.glbFish.createSync(species);
        const group = model.group;
        this.scene.add(group);
        view = { group, speciesId: f.speciesId, fromGlb: model.fromGlb };
        this.fishViews.set(f.entityId, view);
        group.position.set(f.x, -f.depth, -6);
      }
      view.group.position.x = f.x;
      view.group.position.y = -f.depth;
      view.group.rotation.y = f.facing > 0 ? Math.PI / 2 : -Math.PI / 2;
      if (view.fromGlb === false) this.factory.animateTail(view.group, performance.now(), 1.2);
    }
    for (const [id, view] of this.fishViews) {
      if (!seen.has(id)) {
        this.scene.remove(view.group);
        this.fishViews.delete(id);
        // Geometry/materials are shared per factory; nothing else to dispose here.
      }
    }
  }

  private syncHook(snap: RunSnapshot): void {
    const h = snap.hook;
    this.hookGroup.position.set(h.x, -h.depth, 0);
    this.line.update(h.x, h.depth, h.tensionRatio);
  }

  private syncCamera(depth: number): void {
    // Camera trails the hook: slight lead above and behind, smooth damped.
    const targetY = -depth + 4.5;
    this.camera.position.y += (targetY - this.camera.position.y) * 0.08;
    this.camera.position.z = 14;
    this.camera.lookAt(this.hookGroup.position.x * 0.35, targetY - 1.2, -4);
  }

  // ---- Input (spec §16: touch drag / mouse / keys) ---------------------------

  private inputActive = false;
  private inputStartX = 0;
  private inputLastX = 0;

  private bindInput(): void {
    const el = this.renderer.domElement;
    el.addEventListener('pointerdown', this.onPointerDown);
    window.addEventListener('pointermove', this.onPointerMove);
    window.addEventListener('pointerup', this.onPointerUp);
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    el.style.touchAction = 'none';
  }

  private unbindInput(): void {
    const el = this.renderer.domElement;
    el.removeEventListener('pointerdown', this.onPointerDown);
    window.removeEventListener('pointermove', this.onPointerMove);
    window.removeEventListener('pointerup', this.onPointerUp);
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
  }

  private onPointerDown = (e: PointerEvent): void => {
    this.sfx.resume(); // first interaction unlocks audio
    this.inputActive = true;
    this.inputStartX = e.clientX;
    this.inputLastX = e.clientX;
    // Hold = reel (§18 pump-and-reel). Only consumed during a fight.
    this.engine.reel();
  };

  private onPointerMove = (e: PointerEvent): void => {
    if (!this.inputActive) return;
    const dx = e.clientX - this.inputLastX;
    this.inputLastX = e.clientX;
    const norm = Math.max(-1, Math.min(1, dx * 0.12));
    this.engine.setInput(norm);
  };

  private onPointerUp = (): void => {
    this.inputActive = false;
    this.engine.setInput(0);
    this.engine.stopReel();
  };

  private keys = new Set<string>();

  private onKeyDown = (e: KeyboardEvent): void => {
    this.keys.add(e.key);
    this.applyKeys();
  };

  private onKeyUp = (e: KeyboardEvent): void => {
    this.keys.delete(e.key);
    this.applyKeys();
  };

  private applyKeys(): void {
    let dir = 0;
    if (this.keys.has('a') || this.keys.has('ArrowLeft')) dir -= 1;
    if (this.keys.has('d') || this.keys.has('ArrowRight')) dir += 1;
    if (dir !== 0) this.engine.setInput(dir);
    else if (!this.inputActive) this.engine.setInput(0);
    // Space = reel (hold during a fight to win the stamina reel-off).
    if (this.keys.has(' ')) this.engine.reel();
    else if (!this.inputActive) this.engine.stopReel();
  }
}

/**
 * GLB fish pipeline (roadmap 2.3 + 2.6).
 * Loads production GLB models when present in /public/models/fish/<speciesId>.glb,
 * tints them by rarity, and falls back to the procedural mesh when a model is
 * missing — the game must never break on a missing asset (spec §103, §89).
 */
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { FishSpeciesDef } from '@fishkal/shared';
import { FishMeshFactory, RARITY_COLORS } from './fish.js';

export interface FishModelResult {
  group: THREE.Group;
  /** True when a real GLB was used; false = procedural fallback. */
  fromGlb: boolean;
}

export class GlbFishFactory {
  private loader = new GLTFLoader();
  private fallback = new FishMeshFactory();
  private cache = new Map<string, THREE.Group>();

  /** Kick off a prefetch; failures are silently tolerated. */
  prefetch(speciesIds: string[], baseUrls: string[]): void {
    for (const id of speciesIds) void this.loadTemplate(id, baseUrls);
  }

  async create(species: FishSpeciesDef, baseUrls: string[]): Promise<FishModelResult> {
    const template = await this.loadTemplate(species.id, baseUrls);
    if (!template) {
      return { group: this.fallback.create(species), fromGlb: false };
    }
    const group = template.clone(true);
    this.applyRarityTint(group, species);
    group.scale.multiplyScalar(species.size);
    return { group, fromGlb: true };
  }

  /** Synchronous path used by the hot render loop: cache hit → GLB, miss → fallback. */
  createSync(species: FishSpeciesDef): FishModelResult {
    const template = this.cache.get(species.id);
    if (!template) return { group: this.fallback.create(species), fromGlb: false };
    const group = template.clone(true);
    this.applyRarityTint(group, species);
    group.scale.multiplyScalar(species.size);
    return { group, fromGlb: true };
  }

  isGlbAvailable(speciesId: string): boolean {
    return this.cache.has(speciesId);
  }

  private applyRarityTint(root: THREE.Object3D, species: FishSpeciesDef): void {
    // Tint materials toward the rarity color so rarity stays readable on GLBs.
    const tint = new THREE.Color(RARITY_COLORS[species.rarity]);
    root.traverse((obj) => {
      const mesh = obj as THREE.Mesh;
      if (!mesh.isMesh) return;
      const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const m of mats) {
        const std = m as THREE.MeshStandardMaterial;
        if (std.color) std.color.lerp(tint, species.rarity === 'LEGENDARY' ? 0.55 : 0.3);
        if (species.rarity === 'LEGENDARY' || species.rarity === 'EPIC') {
          std.emissive = new THREE.Color(RARITY_COLORS[species.rarity]);
          std.emissiveIntensity = 0.3;
        }
      }
    });
  }

  private loadTemplate(speciesId: string, baseUrls: string[]): Promise<THREE.Group | null> {
    const cached = this.cache.get(speciesId);
    if (cached) return Promise.resolve(cached);
    const inflight = this.inflight.get(speciesId);
    if (inflight) return inflight;

    const attempt = async (): Promise<THREE.Group | null> => {
      for (const base of baseUrls) {
        const url = `${base.replace(/\/$/, '')}/fish/${speciesId}.glb`;
        try {
          const gltf = await this.loader.loadAsync(url);
          const scene = gltf.scene;
          // Normalize: center + fit to ~1 unit length for consistent scaling.
          const box = new THREE.Box3().setFromObject(scene);
          const size = new THREE.Vector3();
          const center = new THREE.Vector3();
          box.getSize(size);
          box.getCenter(center);
          if (size.length() > 0) scene.scale.multiplyScalar(1 / Math.max(size.x, size.y, size.z));
          scene.position.sub(center.multiplyScalar(scene.scale.x));
          this.cache.set(speciesId, scene);
          return scene;
        } catch {
          // Try next base; missing file is expected until assets land (ASSET_REQUIRED).
        }
      }
      return null;
    };
    const p = attempt().then((g) => {
      this.inflight.delete(speciesId);
      return g;
    });
    this.inflight.set(speciesId, p);
    return p;
  }

  private inflight = new Map<string, Promise<THREE.Group | null>>();
}

