      <p className="fk-sub" style={{ fontSize: 12, textAlign: 'center', opacity: 0.7 }}>
        Profile · Referral rewards live · Shop & missions inside the game.
      </p>
    </main>
  );
}

'use client';

import { useEffect, useRef } from 'react';
import { GameView } from '@fishkal/game-renderer';
import type { PerfMode } from '@fishkal/game-renderer';
import type { GameConfig } from '@fishkal/config';
import type { FishkalApi, SubmitRunResponse } from '@fishkal/api-client';

export interface MiniHud {
  score: number;
  depth: number;
  catches: number;
  tension: number;
  state: string;
}

export function GameHost({
  config,
  perfMode,
  api,
  onServerResult,
  onHud,
}: {
  config: GameConfig;
  perfMode?: PerfMode;
  api?: FishkalApi | null;
  onServerResult?: (res: SubmitRunResponse) => void;
  onHud?: (hud: MiniHud) => void;
}) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current) return;
    const view = new GameView({
      container: ref.current,
      config,
      onResults: (stats) => {
        view.sfx.play('record');
        if (!api) return;
        // Server-authoritative scoring (spec §60) — same flow as the website.
        api
          .submitRun({
            maxDepth: stats.maxDepth,
            durationMs: Math.max(1000, Math.round(stats.elapsedMs)),
            catches: view.getEngine().getCatches(),
            clientSeed: Date.now(),
          })
          .then((res) => onServerResult?.(res))
          .catch(() => {
            /* offline: local provisional results remain */
          });
      },
    });
    if (perfMode) view.setPerfMode(perfMode);
    view.startGame();

    const hudTimer = window.setInterval(() => {
      const eng = view.getEngine();
      const hook = eng.getHook();
      const stats = eng.getStats();
      onHud?.({
        score: stats.score,
        depth: Math.round(hook.depth),
        catches: stats.catches,
        tension: hook.tensionRatio,
        state: eng.getState(),
      });
    }, 250);

    return () => {
      window.clearInterval(hudTimer);
      view.dispose();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config, perfMode, api]);

  return (
    <div
      ref={ref}
      style={{ position: 'fixed', inset: 0, background: '#04121F' }}
      aria-label="FISHKAL Deep Catch game"
    />
  );
}

'use client';

import { useEffect, useState } from 'react';
import { FishkalApi } from '@fishkal/api-client';
import type { PlayerProfile } from '@fishkal/api-client';

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:4000';

export function useFishkalSession() {
  const [api] = useState(() => new FishkalApi(API_URL));
  const [profile, setProfile] = useState<PlayerProfile | null>(null);
  const [via, setVia] = useState<'telegram' | 'guest'>('guest');

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const tg = (window as unknown as { Telegram?: { WebApp?: { initData?: string; ready?: () => void; expand?: () => void } } }).Telegram?.WebApp;
      tg?.ready?.();
      tg?.expand?.();
      try {
        const res = tg?.initData
          ? await api.authenticateTelegram(tg.initData)
          : await api.authenticateGuest('Mini App Player');
        if (!cancelled) {
          setProfile(res.profile);
          setVia(tg?.initData ? 'telegram' : 'guest');
        }
      } catch {
        /* preview mode: stay unauthenticated */
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [api]);

  return { api, profile, setProfile, via };
}

/**
 * Telegram Mini App auth helper (spec §35, roadmap Block E).
 * Reads real initData inside Telegram; falls back to guest auth in a plain
 * browser so the mini-app is testable outside Telegram during development.
 */
import type { FishkalApi, PlayerProfile } from '@fishkal/api-client';

interface TgWebApp {
  initData?: string;
  ready?: () => void;
  expand?: () => void;
}

export function tgWebApp(): TgWebApp | null {
  const w = window as unknown as { Telegram?: { WebApp?: TgWebApp } };
  return w.Telegram?.WebApp ?? null;
}

/** Authenticate against the API: Telegram initData when present, else guest. */
export async function authenticate(api: FishkalApi): Promise<{ token: string; profile: PlayerProfile; via: 'telegram' | 'guest' }> {
  const tg = tgWebApp();
  tg?.ready?.();
  tg?.expand?.();
  if (tg?.initData) {
    const res = await api.authenticateTelegram(tg.initData);
    return { ...res, via: 'telegram' };
  }
  const res = await api.authenticateGuest('Mini App Player');
  return { ...res, via: 'guest' };
}

/** Parse a /start deep link referral payload (blocked on token, table ready). */
export function referralCodeFromStart(startParam: string | null): string | null {
  if (!startParam) return null;
  const m = /^ref_([A-Za-z0-9-]{6,64})$/.exec(startParam);
  return m?.[1] ?? null;
}

