function BubbleTrail() {
  return (
    <div aria-hidden style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }}>
      {[...Array(14)].map((_, i) => (
        <span
          key={i}
          style={{
            position: 'absolute',
            left: `${8 + i * 6.4}%`,
            bottom: '-30px',
            width: 6 + (i % 4) * 3,
            height: 6 + (i % 4) * 3,
            borderRadius: '50%',
            background: 'rgba(234,246,244,0.28)',
            animation: `rise ${5 + (i % 5)}s linear ${i * 0.4}s infinite`,
          }}
        />
      ))}
      <style>{`@keyframes rise { to { transform: translateY(-110vh); opacity: 0; } }`}</style>
    </div>
  );
}

function FishSchoil() {
  return (
    <div aria-hidden style={{ position: 'absolute', inset: 0, pointerEvents: 'none', overflow: 'hidden' }}>
      {[...Array(7)].map((_, i) => (
        <span
          key={i}
          style={{
            position: 'absolute',
            top: `${12 + i * 11}%`,
            fontSize: 18 + (i % 3) * 8,
            opacity: 0.5,
            animation: `swim ${9 + (i % 4) * 3}s linear ${i * 1.1}s infinite`,
          }}
        >
          🐟
        </span>
      ))}
      <style>{`@keyframes swim { from { transform: translateX(-8vw); } to { transform: translateX(108vw); } }`}</style>
    </div>
  );
}

'use client';

import dynamic from 'next/dynamic';
import { useState } from 'react';
import { DEFAULT_GAME_CONFIG } from '@fishkal/config';
import type { PerfMode } from '@fishkal/game-renderer';
import { useFishkalSession } from '../../hooks/useFishkalSession';
import type { SubmitRunResponse } from '@fishkal/api-client';
import type { MiniHud } from '@/components/GameHost';

const GameViewHost = dynamic(() => import('@/components/GameHost').then((m) => m.GameHost), {
  ssr: false,
});

export default function MiniAppGame() {
  const { api, profile, setProfile } = useFishkalSession();
  const [hud, setHud] = useState<MiniHud>({ score: 0, depth: 0, catches: 0, tension: 0, state: 'READY' });
  const [server, setServer] = useState<SubmitRunResponse | null>(null);

  return (
    <>
      <GameViewHost
        config={DEFAULT_GAME_CONFIG}
        perfMode={'AUTO' as PerfMode}
        api={api}
        onHud={setHud}
        onServerResult={(res) => {
          setServer(res);
          if (res.record) window.alert(`NEW RECORD! +${res.credits} credits`);
          // Keep the mini-app profile in sync with server-authoritative credits.
          setProfile((p) => (p ? { ...p, credits: p.credits + res.credits, totalScore: Math.max(p.totalScore, res.score) } : p));
        }}
      />
      <div
        style={{
          position: 'fixed',
          top: 12,
          left: 12,
          right: 12,
          display: 'flex',
          justifyContent: 'space-between',
          pointerEvents: 'none',
          color: '#EAF6F4',
          fontVariantNumeric: 'tabular-nums',
          textShadow: '0 1px 4px rgba(0,0,0,.6)',
          fontSize: 14,
          fontWeight: 600,
        }}
      >
        <span>
          {hud.score} pts · {hud.depth}m · 🐟 {hud.catches}
        </span>
        <span>💰 {profile?.credits ?? '—'}</span>
      </div>
      {server && (
        <div
          style={{
            position: 'fixed',
            bottom: 16,
            left: 12,
            right: 12,
            textAlign: 'center',
            color: '#3ED8CB',
            fontWeight: 700,
            textShadow: '0 1px 4px rgba(0,0,0,.6)',
          }}
        >
          Run scored: {server.score} pts · +{server.credits} credits
        </div>
      )}
    </>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { Card } from '@fishkal/design-system';
import { FishkalApi } from '@fishkal/api-client';
import type { LeaderboardRow } from '@fishkal/api-client';

export default function MiniAppLeaderboard() {
  const [rows, setRows] = useState<LeaderboardRow[] | null>(null);

  useEffect(() => {
    const api = new FishkalApi(process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:4000');
    api
      .getLeaderboard('global', 25)
      .then(setRows)
      .catch(() => setRows([]));
  }, []);

  return (
    <main style={{ minHeight: '100dvh', padding: 24 }}>
      <h1 className="fk-headline" style={{ fontSize: 30 }}>
        LEADERBOARD
      </h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {rows?.length === 0 && <p className="fk-sub">No scores yet — be the first to dive.</p>}
        {rows?.map((r) => (
          <Card key={r.playerId} style={{ display: 'flex', justifyContent: 'space-between' }}>
            <span>
              #{r.rank} {r.displayName ?? 'Anonymous Angler'}
            </span>
            <strong>{r.score}</strong>
          </Card>
        ))}
      </div>
    </main>
  );
}
